"use client";

import type { FeatureCollection, GeoJSON, Geometry } from "geojson";
import type { Transition } from "motion/react";
import { domAnimation, LazyMotion } from "motion/react";
import React, {
  memo,
  type ReactNode,
  useCallback,
  useEffect,
  useId,
  useMemo,
  useRef,
  useState,
} from "react";
import { cn } from "@/lib/utils";
import { ParentSize } from "../chart-parent-size";
import { ChoroplethBackground as ChoroplethBackgroundLayer } from "./choropleth-background";
import {
  ChoroplethCameraContext,
  type ChoroplethCameraController,
  type ChoroplethPerspective,
  type ChoroplethZoomTransition,
  useChoroplethCameraController,
} from "./choropleth-camera";
import {
  type ChoroplethFeature,
  type ChoroplethFeatureProperties,
  ChoroplethInteractionShell,
  ChoroplethStableProvider,
  ChoroplethZoomContext,
  type Margin,
  useChoroplethInteraction,
  type ZoomInstance,
} from "./choropleth-context";
import { ChoroplethDotGrid as ChoroplethDotGridLayer } from "./choropleth-dot-grid";
import { ChoroplethFeature as ChoroplethFeatureLayer } from "./choropleth-feature";
import { ChoroplethGraticule as ChoroplethGraticuleLayer } from "./choropleth-graticule";
import { ChoroplethMarker as ChoroplethMarkerLayer } from "./choropleth-marker";
import {
  type ChoroplethMercator,
  createChoroplethMercator,
  projectFeaturePaths,
} from "./choropleth-projection";
import { ChoroplethTooltip as ChoroplethTooltipLayer } from "./choropleth-tooltip";
import {
  choroplethWheelDelta,
  type TransformMatrix,
} from "./choropleth-zoom-matrix";
import { useChoroplethZoomState } from "./use-choropleth-zoom-state";

export interface ChoroplethChartProps {
  /** GeoJSON FeatureCollection data */
  data: FeatureCollection<Geometry, ChoroplethFeatureProperties>;
  /** Chart margins */
  margin?: Partial<Margin>;
  /** Animation duration in milliseconds. Default: 800 */
  animationDuration?: number;
  /** Motion enter transition (spring or cubic-bezier tween). */
  enterTransition?: Transition;
  /** Signature of motion URL state — triggers enter replay when it changes. */
  revealSignature?: string;
  /** Aspect ratio as "width / height". Default: "16 / 9" */
  aspectRatio?: string;
  /** Projection scale. If not provided, auto-calculated based on width */
  scale?: number;
  /** Center coordinates [longitude, latitude]. Default: [0, 20] */
  center?: [number, number];
  /** Translate offset [x, y]. If not provided, auto-calculated to center */
  translate?: [number, number];
  /** Enable zoom and pan. Default: false */
  zoomEnabled?: boolean;
  /** Minimum zoom scale. Default: 0.5 */
  zoomMin?: number;
  /** Maximum zoom scale. Default: 4 */
  zoomMax?: number;
  /** Initial zoom transform */
  initialZoom?: TransformMatrix;
  /**
   * Click a region or marker to fly the camera to it; click it again, the
   * empty map, or press Escape to fly back. Default: false
   */
  clickToZoom?: boolean;
  /** Maximum camera scale when focusing a region. Default: 6 */
  focusMaxZoom?: number;
  /** Duration and easing of the click-to-zoom flight (and camera angle change). */
  zoomTransition?: ChoroplethZoomTransition;
  /**
   * 3D camera: a view for the zoomed-out map and one for a focused region,
   * e.g. flat overview that swings to look from the east when you zoom in.
   */
  perspective?: ChoroplethPerspective;
  /** Additional class name for the container */
  className?: string;
  /** Child components (ChoroplethFeature, ChoroplethGraticule, ChoroplethTooltip) */
  children: ReactNode;
}

const DEFAULT_MARGIN: Margin = { top: 0, right: 0, bottom: 0, left: 0 };

// Known SVG component displayNames
const SVG_COMPONENT_NAMES = new Set([
  "ChoroplethFeature",
  "ChoroplethGraticule",
  "ChoroplethTooltip",
  "ChoroplethDotGrid",
  "ChoroplethMarker",
]);

const SVG_COMPONENT_TYPES = new Set<unknown>([
  ChoroplethFeatureLayer,
  ChoroplethGraticuleLayer,
  ChoroplethTooltipLayer,
  ChoroplethDotGridLayer,
  ChoroplethMarkerLayer,
]);

// Static layers drawn behind the map: they don't zoom or tilt.
const BACKDROP_COMPONENT_NAMES = new Set(["ChoroplethBackground"]);
const BACKDROP_COMPONENT_TYPES = new Set<unknown>([ChoroplethBackgroundLayer]);

function isChoroplethBackdropChild(type: unknown): boolean {
  if (
    BACKDROP_COMPONENT_TYPES.has(type) ||
    BACKDROP_COMPONENT_TYPES.has(resolveComponentType(type))
  ) {
    return true;
  }
  const displayName = getComponentDisplayName(type);
  return displayName !== null && BACKDROP_COMPONENT_NAMES.has(displayName);
}

function resolveComponentType(type: unknown): unknown {
  if (
    typeof type === "object" &&
    type !== null &&
    "type" in type &&
    (type as { type?: unknown }).type
  ) {
    return (type as { type: unknown }).type;
  }
  return type;
}

function getComponentDisplayName(type: unknown): string | null {
  if (typeof type === "function") {
    const fn = type as { displayName?: string; name?: string };
    return fn.displayName ?? fn.name ?? null;
  }
  if (typeof type === "object" && type !== null) {
    const wrapped = type as {
      displayName?: string;
      type?: { displayName?: string; name?: string };
    };
    if (wrapped.displayName) {
      return wrapped.displayName;
    }
    const inner = wrapped.type;
    if (typeof inner === "function") {
      const innerFn = inner as { displayName?: string; name?: string };
      return innerFn.displayName ?? innerFn.name ?? null;
    }
  }
  return null;
}

function isChoroplethSvgChild(type: unknown): boolean {
  if (SVG_COMPONENT_TYPES.has(type)) {
    return true;
  }
  const resolved = resolveComponentType(type);
  if (resolved !== type && SVG_COMPONENT_TYPES.has(resolved)) {
    return true;
  }
  const displayName = getComponentDisplayName(type);
  return displayName !== null && SVG_COMPONENT_NAMES.has(displayName);
}

// HTML elements that should render in overlay layer
const HTML_ELEMENTS = new Set(["div", "span", "button", "p", "a"]);

// Separate children into SVG and overlay layers
function separateChildren(children: ReactNode): {
  backdropChildren: React.ReactNode[];
  svgChildren: React.ReactNode[];
  overlayChildren: React.ReactNode[];
} {
  const childArray = React.Children.toArray(children);
  const backdropChildren: React.ReactNode[] = [];
  const svgChildren: React.ReactNode[] = [];
  const overlayChildren: React.ReactNode[] = [];

  for (const child of childArray) {
    if (!React.isValidElement(child)) {
      svgChildren.push(child);
      continue;
    }

    if (isChoroplethBackdropChild(child.type)) {
      backdropChildren.push(child);
    } else if (isChoroplethSvgChild(child.type)) {
      svgChildren.push(child);
    } else if (typeof child.type === "string") {
      if (HTML_ELEMENTS.has(child.type)) {
        overlayChildren.push(child);
      } else {
        svgChildren.push(child);
      }
    } else {
      overlayChildren.push(child);
    }
  }

  return { backdropChildren, svgChildren, overlayChildren };
}

const DEFAULT_INITIAL_ZOOM: TransformMatrix = {
  scaleX: 1,
  scaleY: 1,
  translateX: 0,
  translateY: 0,
  skewX: 0,
  skewY: 0,
};

interface ChoroplethMercatorContentProps {
  mercator: ChoroplethMercator;
  featurePaths: readonly (string | null)[];
  data: FeatureCollection<Geometry, ChoroplethFeatureProperties>;
  width: number;
  height: number;
  innerWidth: number;
  innerHeight: number;
  margin: Margin;
  animationDuration: number;
  enterTransition?: Transition;
  revealEpoch: number;
  isLoaded: boolean;
  containerRef: React.RefObject<HTMLDivElement | null>;
  backdropChildren: React.ReactNode[];
  svgChildren: React.ReactNode[];
  overlayChildren: React.ReactNode[];
  zoom?: ZoomInstance<SVGSVGElement>;
  cameraOptions: CameraOptions;
}

interface CameraOptions {
  clickToZoom: boolean;
  focusMaxZoom: number;
  zoomTransition?: ChoroplethZoomTransition;
  perspective?: ChoroplethPerspective;
}

function fadeStops(edge: number, active: boolean) {
  const outer = active ? 0 : 1;
  return [
    { offset: "0%", opacity: outer },
    { offset: `${edge}%`, opacity: 1 },
    { offset: `${100 - edge}%`, opacity: 1 },
    { offset: "100%", opacity: outer },
  ];
}

/** Horizontal × vertical edge fade in the svg's own (untransformed) space. */
function ViewportFadeMask({
  id,
  width,
  height,
  edgeFade,
  active,
}: {
  id: string;
  width: number;
  height: number;
  edgeFade: number;
  active: boolean;
}) {
  const stops = fadeStops(edgeFade, active);
  // stop-opacity is a CSS property, so the fade eases in as the camera moves.
  const stopNodes = stops.map((stop) => (
    <stop
      key={stop.offset}
      offset={stop.offset}
      stopColor="white"
      style={{
        stopOpacity: stop.opacity,
        transition: "stop-opacity 0.4s ease-out",
      }}
    />
  ));
  return (
    <defs>
      <linearGradient id={`${id}-h`} x1="0" x2="1" y1="0" y2="0">
        {stopNodes}
      </linearGradient>
      <linearGradient id={`${id}-v`} x1="0" x2="0" y1="0" y2="1">
        {stopNodes}
      </linearGradient>
      <mask
        height={height}
        id={`${id}-hm`}
        maskUnits="userSpaceOnUse"
        width={width}
        x={0}
        y={0}
      >
        <rect fill={`url(#${id}-h)`} height={height} width={width} />
      </mask>
      <mask
        height={height}
        id={id}
        maskUnits="userSpaceOnUse"
        width={width}
        x={0}
        y={0}
      >
        <g mask={`url(#${id}-hm)`}>
          <rect fill={`url(#${id}-v)`} height={height} width={width} />
        </g>
      </mask>
    </defs>
  );
}

const ChoroplethSvg = memo(function ChoroplethSvg({
  height,
  width,
  svgChildren,
  zoom,
  camera,
}: {
  height: number;
  width: number;
  svgChildren: React.ReactNode[];
  zoom?: ZoomInstance<SVGSVGElement>;
  camera: ChoroplethCameraController;
}) {
  const { setHoveredFeatureIndex, setTooltipData, setMarkerTooltip } =
    useChoroplethInteraction();
  const { api, svgRef, cameraRef, edgeFade, edgeFadeActive } = camera;
  const fadeId = `choropleth-edge-fade-${useId().replace(/:/g, "")}`;
  const zoomContainerRef = zoom?.containerRef;

  const handleMouseLeave = useCallback(() => {
    setHoveredFeatureIndex(null);
    setTooltipData(null);
    setMarkerTooltip?.(null);
  }, [setHoveredFeatureIndex, setTooltipData, setMarkerTooltip]);

  const setSvgRef = useCallback(
    (node: SVGSVGElement | null) => {
      svgRef.current = node;
      if (zoomContainerRef) {
        zoomContainerRef.current = node;
      }
    },
    [svgRef, zoomContainerRef]
  );

  // Clicking empty map (not a region or marker) flies back out.
  const handleClick = useCallback(
    (event: React.MouseEvent<SVGSVGElement>) => {
      if (
        api.enabled &&
        api.focusedKey !== null &&
        event.target === event.currentTarget &&
        !api.wasDrag()
      ) {
        api.reset();
      }
    },
    [api]
  );

  let cursor: string | undefined;
  if (zoom) {
    cursor = zoom.isDragging ? "grabbing" : "grab";
  }

  return (
    <svg
      aria-hidden="true"
      height={height}
      onClick={handleClick}
      onMouseLeave={handleMouseLeave}
      ref={setSvgRef}
      style={{
        // Draws past its own box: the tilted plane would otherwise show the
        // svg edge as a slanted cut. The untransformed wrapper clips instead.
        contain: "layout style",
        overflow: "visible",
        cursor,
        touchAction: zoom ? "none" : "manipulation",
      }}
      width={width}
    >
      {edgeFade > 0 ? (
        <ViewportFadeMask
          active={edgeFadeActive}
          edgeFade={edgeFade}
          height={height}
          id={fadeId}
          width={width}
        />
      ) : null}
      {/* Mask lives outside the camera, so it stays on the chart's edges. */}
      <g mask={edgeFade > 0 ? `url(#${fadeId})` : undefined}>
        <g ref={cameraRef}>
          <g
            style={{
              transition: zoom?.isDragging
                ? "none"
                : "transform 0.18s ease-out",
            }}
            transform={zoom ? zoom.toString() : undefined}
          >
            {svgChildren}
          </g>
        </g>
      </g>
    </svg>
  );
});

const ChoroplethMercatorContent = memo(function ChoroplethMercatorContent({
  mercator,
  featurePaths,
  data,
  width,
  height,
  innerWidth,
  innerHeight,
  margin,
  animationDuration,
  enterTransition,
  revealEpoch,
  isLoaded,
  containerRef,
  backdropChildren,
  svgChildren,
  overlayChildren,
  zoom,
  cameraOptions,
}: ChoroplethMercatorContentProps) {
  const camera = useChoroplethCameraController({
    ...cameraOptions,
    width,
    height,
    mercator,
    features: data.features,
    onBeforeFocus: zoom?.reset,
  });

  const pathGenerator = useCallback(
    (feature: ChoroplethFeature) => mercator.path(feature) ?? undefined,
    [mercator]
  );

  const rawPathGenerator = useCallback(
    (geo: GeoJSON) => mercator.path(geo),
    [mercator]
  );

  const projectPoint = useCallback(
    (coords: [number, number]): [number, number] | null => {
      const projected = mercator.projection(coords);
      if (!projected) {
        return null;
      }
      return projected as [number, number];
    },
    [mercator]
  );

  const stableValue = useMemo(
    () => ({
      features: data.features,
      featureCollection: data,
      featurePaths,
      pathGenerator,
      rawPathGenerator,
      projectPoint,
      width,
      height,
      innerWidth,
      innerHeight,
      margin,
      containerRef,
      isLoaded,
      animationDuration,
      enterTransition,
      revealEpoch,
    }),
    [
      animationDuration,
      containerRef,
      data,
      enterTransition,
      featurePaths,
      height,
      innerHeight,
      innerWidth,
      isLoaded,
      margin,
      pathGenerator,
      projectPoint,
      rawPathGenerator,
      revealEpoch,
      width,
    ]
  );

  return (
    <ChoroplethZoomContext.Provider value={{ zoom: zoom ?? null }}>
      <ChoroplethCameraContext.Provider value={camera.api}>
        <ChoroplethStableProvider value={stableValue}>
          <ChoroplethInteractionShell>
            <div
              className="relative h-full w-full"
              onPointerDown={camera.onPointerDown}
              onPointerLeave={camera.onPointerLeave}
              onPointerMove={camera.onPointerMove}
              ref={containerRef}
            >
              {backdropChildren.length > 0 ? (
                <svg
                  aria-hidden="true"
                  className="pointer-events-none absolute inset-0"
                  height={height}
                  width={width}
                >
                  {backdropChildren}
                </svg>
              ) : null}
              {/* Clip box: never transformed, so the map is cut by the chart frame. */}
              <div
                className="relative h-full w-full"
                // Inline so wrappers that force `overflow: visible` on
                // descendants (e.g. gallery frames) can't undo the clip.
                style={{
                  overflow: "hidden",
                  perspective: camera.hasPerspective
                    ? `${camera.depth}px`
                    : undefined,
                }}
              >
                <div
                  className="h-full w-full"
                  ref={camera.planeRef}
                  style={{
                    transformOrigin: "50% 60%",
                    // A tilt that changes every frame otherwise makes Chrome
                    // drop to a low-res raster until the motion settles.
                    willChange: camera.hasPerspective ? "transform" : undefined,
                  }}
                >
                  <ChoroplethSvg
                    camera={camera}
                    height={height}
                    svgChildren={svgChildren}
                    width={width}
                    zoom={zoom}
                  />
                </div>
              </div>
              {overlayChildren}
            </div>
          </ChoroplethInteractionShell>
        </ChoroplethStableProvider>
      </ChoroplethCameraContext.Provider>
    </ChoroplethZoomContext.Provider>
  );
});

/** Owns the zoom state (replaces visx `<Zoom>`'s render prop). */
function ChoroplethZoom({
  width,
  height,
  initialTransformMatrix,
  scaleMin,
  scaleMax,
  children,
}: {
  width: number;
  height: number;
  initialTransformMatrix: TransformMatrix;
  scaleMin: number;
  scaleMax: number;
  children: (zoom: ZoomInstance<SVGSVGElement>) => ReactNode;
}) {
  const zoom = useChoroplethZoomState<SVGSVGElement>({
    width,
    height,
    initialTransformMatrix,
    scaleXMin: scaleMin,
    scaleXMax: scaleMax,
    scaleYMin: scaleMin,
    scaleYMax: scaleMax,
    wheelDelta: choroplethWheelDelta,
  });
  return children(zoom);
}

function ChoroplethChartInner({
  data,
  width,
  height,
  margin: marginProp,
  animationDuration,
  enterTransition,
  revealSignature = "",
  scale: scaleProp,
  center,
  translate: translateProp,
  zoomEnabled,
  zoomMin,
  zoomMax,
  initialZoom,
  cameraOptions,
  children,
}: {
  cameraOptions: CameraOptions;
  data: FeatureCollection<Geometry, ChoroplethFeatureProperties>;
  width: number;
  height: number;
  margin: Margin;
  animationDuration: number;
  enterTransition?: Transition;
  revealSignature?: string;
  scale?: number;
  center: [number, number];
  translate?: [number, number];
  zoomEnabled: boolean;
  zoomMin: number;
  zoomMax: number;
  initialZoom: TransformMatrix;
  children: ReactNode;
}) {
  const containerRef = useRef<HTMLDivElement>(null);
  const [isLoaded, setIsLoaded] = useState(false);
  const [revealEpoch, setRevealEpoch] = useState(1);

  // ChoroplethChart spreads a fresh margin object every render; key it on
  // its values so the memoized content and stable context survive.
  const margin = useMemo(
    () => ({
      top: marginProp.top,
      right: marginProp.right,
      bottom: marginProp.bottom,
      left: marginProp.left,
    }),
    [marginProp.top, marginProp.right, marginProp.bottom, marginProp.left]
  );

  const innerWidth = width - margin.left - margin.right;
  const innerHeight = height - margin.top - margin.bottom;

  const scale = scaleProp ?? (innerWidth / 630) * 100;

  const translateX = translateProp?.[0] ?? innerWidth / 2 + margin.left;
  const translateY = translateProp?.[1] ?? innerHeight / 2 + margin.top + 50;
  const [centerX, centerY] = center;

  // Projection + per-feature paths, recomputed only when their inputs change
  // (visx <Mercator> rebuilt both on every render).
  const mercator = useMemo(
    () =>
      createChoroplethMercator({
        scale,
        translate: [translateX, translateY],
        center: [centerX, centerY],
      }),
    [scale, translateX, translateY, centerX, centerY]
  );
  const featurePaths = useMemo(
    () => projectFeaturePaths(mercator, data.features),
    [mercator, data.features]
  );

  const { backdropChildren, svgChildren, overlayChildren } = useMemo(
    () => separateChildren(children),
    [children]
  );

  // Replay the reveal when motion settings change. Adjusted during render
  // ("store previous props in state") instead of setState in an effect, so a
  // replay costs one render rather than a commit plus a cascading re-render.
  const [revealKey, setRevealKey] = useState({
    animationDuration,
    revealSignature,
  });
  if (
    revealKey.animationDuration !== animationDuration ||
    revealKey.revealSignature !== revealSignature
  ) {
    setRevealKey({ animationDuration, revealSignature });
    setRevealEpoch((n) => n + 1);
    setIsLoaded(false);
  }

  // biome-ignore lint/correctness/useExhaustiveDependencies: revealSignature
  useEffect(() => {
    const timeout = setTimeout(() => {
      setIsLoaded(true);
    }, animationDuration);
    return () => clearTimeout(timeout);
  }, [animationDuration, revealSignature]);

  if (width < 10 || height < 10) {
    return null;
  }

  const mercatorContentProps = {
    animationDuration,
    backdropChildren,
    cameraOptions,
    containerRef,
    data,
    enterTransition,
    height,
    innerHeight,
    innerWidth,
    isLoaded,
    margin,
    overlayChildren,
    revealEpoch,
    svgChildren,
    width,
  };

  const content = (zoom?: ZoomInstance<SVGSVGElement>) => (
    <ChoroplethMercatorContent
      {...mercatorContentProps}
      featurePaths={featurePaths}
      mercator={mercator}
      zoom={zoom}
    />
  );

  if (zoomEnabled) {
    return (
      <ChoroplethZoom
        height={height}
        initialTransformMatrix={initialZoom}
        scaleMax={zoomMax}
        scaleMin={zoomMin}
        width={width}
      >
        {content}
      </ChoroplethZoom>
    );
  }

  return content();
}

export function ChoroplethChart({
  data,
  margin: marginProp,
  animationDuration = 800,
  enterTransition,
  revealSignature,
  aspectRatio = "16 / 9",
  scale,
  center = [0, 20],
  translate,
  zoomEnabled = false,
  zoomMin = 0.5,
  zoomMax = 4,
  initialZoom = DEFAULT_INITIAL_ZOOM,
  clickToZoom = false,
  focusMaxZoom = 6,
  zoomTransition,
  perspective,
  className = "",
  children,
}: ChoroplethChartProps) {
  const margin = { ...DEFAULT_MARGIN, ...marginProp };
  // Keyed on values so inline literals don't re-render the memoized map.
  const zoomDuration = zoomTransition?.duration;
  const zoomEase = zoomTransition?.ease?.join(",");
  const perspectiveKey = perspective ? JSON.stringify(perspective) : "";
  const cameraOptions = useMemo<CameraOptions>(
    () => ({ clickToZoom, focusMaxZoom, zoomTransition, perspective }),
    [clickToZoom, focusMaxZoom, zoomDuration, zoomEase, perspectiveKey]
  );

  return (
    <LazyMotion features={domAnimation}>
      <div className={cn("relative w-full", className)} style={{ aspectRatio }}>
        <ParentSize debounceTime={10}>
          {({ width, height }) =>
            width > 0 && height > 0 ? (
              <ChoroplethChartInner
                animationDuration={animationDuration}
                cameraOptions={cameraOptions}
                center={center}
                data={data}
                enterTransition={enterTransition}
                height={height}
                initialZoom={initialZoom}
                margin={margin}
                revealSignature={revealSignature}
                scale={scale}
                translate={translate}
                width={width}
                zoomEnabled={zoomEnabled}
                zoomMax={zoomMax}
                zoomMin={zoomMin}
              >
                {children}
              </ChoroplethChartInner>
            ) : null
          }
        </ParentSize>
      </div>
    </LazyMotion>
  );
}

ChoroplethChart.displayName = "ChoroplethChart";

export default ChoroplethChart;

import {
  type GeoPath,
  type GeoPermissibleObjects,
  type GeoProjection,
  geoGraticule,
  geoMercator,
  geoPath,
} from "d3-geo";
import type { MultiLineString } from "geojson";

/** What the choropleth reads from its projection (visx `<Mercator>` render props). */
export interface ChoroplethMercator {
  path: GeoPath<unknown, GeoPermissibleObjects>;
  projection: GeoProjection;
}

export interface ChoroplethMercatorConfig {
  scale?: number;
  translate?: [number, number];
  center?: [number, number];
}

/**
 * d3 equivalent of visx `<Mercator scale translate center>`: visx applied
 * each option only when truthy, in this order (so `scale={0}` keeps d3's
 * default scale).
 */
export function createChoroplethMercator({
  scale,
  translate,
  center,
}: ChoroplethMercatorConfig): ChoroplethMercator {
  const projection = geoMercator();
  if (scale) {
    projection.scale(scale);
  }
  if (translate) {
    projection.translate(translate);
  }
  if (center) {
    projection.center(center);
  }
  return { path: geoPath(projection), projection };
}

/** One SVG path string per feature (null when the geometry draws nothing). */
export function projectFeaturePaths(
  mercator: ChoroplethMercator,
  features: readonly GeoPermissibleObjects[]
): (string | null)[] {
  return features.map((feature) => mercator.path(feature) ?? null);
}

/**
 * Graticule path as visx `<Graticule graticule={...} step={step}>` drew it:
 * the full `geoGraticule()` MultiLineString (minor `step`, default 10°, plus
 * the major lines) through the projection's path, `""` when empty.
 */
export function graticulePath(
  path: (object: MultiLineString) => string | null | undefined,
  step?: [number, number]
): string {
  const graticule = geoGraticule();
  if (step) {
    graticule.step(step);
  }
  return path(graticule()) || "";
}

/**
 * 2D affine matrix helpers for the choropleth zoom. Same fields, formulas and
 * operation order as `@visx/zoom` 4.0.0 `util/matrix`, so every wheel / drag /
 * button step produces a bit-identical transform.
 */

export interface TransformMatrix {
  scaleX: number;
  scaleY: number;
  translateX: number;
  translateY: number;
  skewX: number;
  skewY: number;
}

export interface Point {
  x: number;
  y: number;
}

export type Translate = Pick<TransformMatrix, "translateX" | "translateY">;
export type Scale = Pick<TransformMatrix, "scaleX" | "scaleY">;

export interface ScaleSignature {
  scaleX: TransformMatrix["scaleX"];
  scaleY?: TransformMatrix["scaleY"];
  point?: Point;
}

export interface ScaleLimits {
  scaleXMin: number;
  scaleXMax: number;
  scaleYMin: number;
  scaleYMax: number;
}

export function identityMatrix(): TransformMatrix {
  return {
    scaleX: 1,
    scaleY: 1,
    translateX: 0,
    translateY: 0,
    skewX: 0,
    skewY: 0,
  };
}

export function createMatrix({
  scaleX = 1,
  scaleY = 1,
  translateX = 0,
  translateY = 0,
  skewX = 0,
  skewY = 0,
}: Partial<TransformMatrix>): TransformMatrix {
  return { scaleX, scaleY, translateX, translateY, skewX, skewY };
}

export function inverseMatrix({
  scaleX,
  scaleY,
  translateX,
  translateY,
  skewX,
  skewY,
}: TransformMatrix): TransformMatrix {
  const denominator = scaleX * scaleY - skewY * skewX;
  return {
    scaleX: scaleY / denominator,
    scaleY: scaleX / denominator,
    translateX: (scaleY * translateX - skewX * translateY) / -denominator,
    translateY: (skewY * translateX - scaleX * translateY) / denominator,
    skewX: skewX / -denominator,
    skewY: skewY / -denominator,
  };
}

export function applyMatrixToPoint(
  matrix: TransformMatrix,
  { x, y }: Point
): Point {
  return {
    x: matrix.scaleX * x + matrix.skewX * y + matrix.translateX,
    y: matrix.skewY * x + matrix.scaleY * y + matrix.translateY,
  };
}

export function applyInverseMatrixToPoint(
  matrix: TransformMatrix,
  { x, y }: Point
): Point {
  return applyMatrixToPoint(inverseMatrix(matrix), { x, y });
}

export function scaleMatrix(
  scaleX: number,
  maybeScaleY: number | undefined = undefined
): TransformMatrix {
  const scaleY = maybeScaleY || scaleX;
  return createMatrix({ scaleX, scaleY });
}

export function translateMatrix(
  translateX: number,
  translateY: number
): TransformMatrix {
  return createMatrix({ translateX, translateY });
}

export function multiplyMatrices(
  matrix1: TransformMatrix,
  matrix2: TransformMatrix
): TransformMatrix {
  return {
    scaleX: matrix1.scaleX * matrix2.scaleX + matrix1.skewX * matrix2.skewY,
    scaleY: matrix1.skewY * matrix2.skewX + matrix1.scaleY * matrix2.scaleY,
    translateX:
      matrix1.scaleX * matrix2.translateX +
      matrix1.skewX * matrix2.translateY +
      matrix1.translateX,
    translateY:
      matrix1.skewY * matrix2.translateX +
      matrix1.scaleY * matrix2.translateY +
      matrix1.translateY,
    skewX: matrix1.scaleX * matrix2.skewX + matrix1.skewX * matrix2.scaleY,
    skewY: matrix1.skewY * matrix2.scaleX + matrix1.scaleY * matrix2.skewY,
  };
}

/** Left-to-right composition (visx folds pairwise from the left). */
export function composeMatrices(
  ...matrices: [TransformMatrix, ...TransformMatrix[]]
): TransformMatrix {
  let result = matrices[0];
  for (let i = 1; i < matrices.length; i++) {
    result = multiplyMatrices(result, matrices[i] as TransformMatrix);
  }
  return result;
}

/** `matrix(a, b, c, d, e, f)` exactly as visx `toString()` writes it. */
export function matrixToString({
  scaleX,
  scaleY,
  translateX,
  translateY,
  skewX,
  skewY,
}: TransformMatrix): string {
  return `matrix(${scaleX}, ${skewY}, ${skewX}, ${scaleY}, ${translateX}, ${translateY})`;
}

/**
 * visx default `constrain`: reject (keep `prev`) when the next scale leaves
 * the limits. Pan is never constrained.
 */
export function constrainScale(
  next: TransformMatrix,
  prev: TransformMatrix,
  { scaleXMin, scaleXMax, scaleYMin, scaleYMax }: ScaleLimits
): TransformMatrix {
  const { scaleX, scaleY } = next;
  const shouldConstrainScaleX = scaleX > scaleXMax || scaleX < scaleXMin;
  const shouldConstrainScaleY = scaleY > scaleYMax || scaleY < scaleYMin;
  if (shouldConstrainScaleX || shouldConstrainScaleY) {
    return prev;
  }
  return next;
}

/**
 * visx `scale()`: scale by `scaleX` / `scaleY` (defaults to `scaleX`) around
 * `point` (in container coordinates; centre of `width` x `height` if absent).
 */
export function scaleMatrixAroundPoint(
  matrix: TransformMatrix,
  { scaleX, scaleY: maybeScaleY, point }: ScaleSignature,
  width: number,
  height: number
): TransformMatrix {
  const scaleY = maybeScaleY || scaleX;
  const cleanPoint = point || { x: width / 2, y: height / 2 };
  const translate = applyInverseMatrixToPoint(matrix, cleanPoint);
  return composeMatrices(
    matrix,
    translateMatrix(translate.x, translate.y),
    scaleMatrix(scaleX, scaleY),
    translateMatrix(-translate.x, -translate.y)
  );
}

/** visx default `wheelDelta` (Zoom without a custom one). */
export function defaultWheelDelta(event: { deltaY: number }): Scale {
  return -event.deltaY > 0
    ? { scaleX: 1.1, scaleY: 1.1 }
    : { scaleX: 0.9, scaleY: 0.9 };
}

/** The `wheelDelta` ChoroplethChart passes: 5% per wheel event. */
export function choroplethWheelDelta(event: { deltaY: number }): Scale {
  const zoomScale = event.deltaY > 0 ? 0.95 : 1.05;
  return { scaleX: zoomScale, scaleY: zoomScale };
}

/** Pinch progress handed to `pinchDelta` (the use-gesture fields visx read). */
export interface PinchDeltaState {
  /** `[scale offset, angle]` now. */
  offset: [number, number];
  /** `[scale offset, angle]` when the pinch started. */
  lastOffset: [number, number];
  /** Pinch centre in client coordinates. */
  origin: [number, number];
}

/** visx default `pinchDelta`: a 10% step towards the pinch direction. */
export function defaultPinchDelta({
  offset: [s],
  lastOffset: [lastS],
}: PinchDeltaState): Scale {
  return {
    scaleX: s - lastS < 0 ? 0.9 : 1.1,
    scaleY: s - lastS < 0 ? 0.9 : 1.1,
  };
}

const LINE_HEIGHT = 40;
const PAGE_HEIGHT = 800;

/** use-gesture `wheelValues()[1]`: deltaY in pixels. */
export function wheelDeltaYPixels(event: {
  deltaY: number;
  deltaMode: number;
}): number {
  if (event.deltaMode === 1) {
    return event.deltaY * LINE_HEIGHT;
  }
  if (event.deltaMode === 2) {
    return event.deltaY * PAGE_HEIGHT;
  }
  return event.deltaY;
}

/** use-gesture `PINCH_WHEEL_RATIO`: ctrl+wheel pixels per unit of pinch. */
export const PINCH_WHEEL_RATIO = 100;

/** use-gesture drag `tapsThreshold` (also the drag start threshold). */
export const DRAG_THRESHOLD_PX = 3;

"use client";

import type { WheelEvent as ReactWheelEvent, RefObject } from "react";
import { useCallback, useEffect, useRef, useState } from "react";
import { type LocalPointEvent, localPoint } from "../local-point";
import {
  applyInverseMatrixToPoint,
  applyMatrixToPoint,
  composeMatrices,
  constrainScale,
  DRAG_THRESHOLD_PX,
  defaultPinchDelta,
  defaultWheelDelta,
  identityMatrix,
  inverseMatrix,
  matrixToString,
  PINCH_WHEEL_RATIO,
  type PinchDeltaState,
  type Point,
  type Scale,
  type ScaleSignature,
  scaleMatrixAroundPoint,
  type TransformMatrix,
  type Translate,
  translateMatrix,
  wheelDeltaYPixels,
} from "./choropleth-zoom-matrix";

/**
 * Hand-written replacement for `@visx/zoom` 4.0.0 `<Zoom>` and the
 * `@use-gesture/react` recognisers it binds.
 *
 * The zoom API below is a transcription of visx's Zoom.js: the same React
 * state (`transformMatrix`, `isDragging`, `startPoint`, `startTranslate`),
 * the same matrix ref updated inside the `setTransformMatrix` updater, and
 * the same render-time closures. That matters beyond style: on the first
 * ctrl+wheel of a trackpad pinch, use-gesture calls the wheel handler and
 * then the pinch handler in one event, and whether the pinch step sees the
 * wheel step depends on whether React computed the first update eagerly.
 * Mirroring visx's state lets React make that call exactly as it did.
 *
 * The gesture layer reproduces use-gesture:
 * - Drag-pan with the primary button / one finger: pointer capture on the hit
 *   element, starts once the pointer moved 3 px on an axis (the first 3 px
 *   are not applied), the pointer-up position is applied once more, and a
 *   click after a real drag (> 3 px) is swallowed in the capture phase.
 * - Wheel (non-passive): one `wheelDelta` step per event around the cursor,
 *   skipped while pinching.
 * - Pinch: two pointers, ctrl+wheel (trackpads) or WebKit gesture events
 *   (desktop Safari). Each pinch event applies one `pinchDelta` step (default
 *   0.9 / 1.1) around the pinch centre minus the container's client rect,
 *   including one step when the pinch starts and one when it ends (a
 *   ctrl+wheel pinch ends 140 ms after its last event). A pinch cancels a
 *   drag.
 * - Scale steps that would leave `scaleXMin..scaleXMax` /
 *   `scaleYMin..scaleYMax` are rejected (not clamped). Pan is unconstrained.
 */

export interface ProvidedZoom<ElementType> {
  /** Sets translateX/Y to the center defined by width and height. */
  center: () => void;
  /** Sets the transform matrix to the identity matrix. */
  clear: () => void;
  /** Scales around `point` (or the centre of the canvas). */
  scale: (scale: ScaleSignature) => void;
  /** Multiplies the current transform matrix by the specified translation. */
  translate: (translate: Translate) => void;
  /** Translates to a specific x,y point. */
  translateTo: (point: Point) => void;
  /** Sets the translation of the current transform matrix. */
  setTranslate: (translate: Translate) => void;
  /** Sets the transform matrix, constraining its scale. */
  setTransformMatrix: (matrix: TransformMatrix) => void;
  /** Resets the transform to the initial transform. */
  reset: () => void;
  /** Wheel handler: one `wheelDelta` step around the pointer. */
  handleWheel: (event: ReactWheelEvent | WheelEvent) => void;
  /** Sets isDragging to false. */
  dragEnd: () => void;
  /** Pans by the pointer's distance from the drag start. */
  dragMove: (
    event: LocalPointEvent,
    options?: { offsetX?: number; offsetY?: number }
  ) => void;
  /** Records the drag start point and sets isDragging to true. */
  dragStart: (event: LocalPointEvent) => void;
  /** `matrix(scaleX, skewY, skewX, scaleY, translateX, translateY)` */
  toString: () => string;
  /** Inverse of the current transform matrix. */
  invert: () => TransformMatrix;
  /** String form of the inverse matrix. */
  toStringInvert: () => string;
  applyToPoint: (point: Point) => Point;
  applyInverseToPoint: (point: Point) => Point;
  /** Ref for the element that receives the gestures. */
  containerRef: RefObject<ElementType | null>;
}

export interface ZoomState {
  initialTransformMatrix: TransformMatrix;
  transformMatrix: TransformMatrix;
  isDragging: boolean;
}

export type ZoomInstance<E extends Element> = ProvidedZoom<E> & ZoomState;

export interface ChoroplethZoomOptions {
  width: number;
  height: number;
  initialTransformMatrix?: TransformMatrix;
  scaleXMin?: number;
  scaleXMax?: number;
  scaleYMin?: number;
  scaleYMax?: number;
  wheelDelta?: (event: ReactWheelEvent | WheelEvent) => Scale;
  pinchDelta?: (state: PinchDeltaState) => Scale;
  constrain?: (
    transform: TransformMatrix,
    prevTransform: TransformMatrix
  ) => TransformMatrix;
}

const DEFAULT_INITIAL: TransformMatrix = identityMatrix();
/** use-gesture `TimeoutStore` default: a ctrl+wheel pinch ends 140 ms after its last event. */
const WHEEL_END_MS = 140;

export interface DragGesture {
  pointerId: number;
  /** Pointer is down and tracked (use-gesture `_pointerActive`). */
  pointerActive: boolean;
  /** Gesture not ended / cancelled (use-gesture `_active`). */
  active: boolean;
  /** Past the threshold at least once (use-gesture `state.active`). */
  started: boolean;
  last: [number, number];
  movement: [number, number];
  distance: [number, number];
  intentional: boolean;
  /** Last event handed to the handlers (re-sent after a cancel). */
  event: PointerEvent | null;
}

interface PinchGesture {
  active: boolean;
  source: "pointer" | "wheel" | "gesture" | null;
  /** Persistent scale offset (use-gesture pinch `offset[0]`, starts at 1). */
  offset: number;
  lastOffset: number;
  /** ctrl+wheel: accumulated movement. */
  movement: number;
  initialDistance: number;
  origin: [number, number];
  memo: { top: number; left: number } | undefined;
  pointers: Map<number, { clientX: number; clientY: number }>;
}

/** What visx `handlePinch` read from the use-gesture pinch state. */
interface PinchHandlerState extends PinchDeltaState {
  memo: { top: number; left: number } | undefined;
}

export function createDragGesture(
  event: Pick<PointerEvent, "pointerId" | "clientX" | "clientY">
): DragGesture {
  return {
    pointerId: event.pointerId,
    pointerActive: true,
    active: true,
    started: false,
    last: [event.clientX, event.clientY],
    movement: [0, 0],
    distance: [0, 0],
    intentional: false,
    event: null,
  };
}

/**
 * Feed one pointer move into the drag (use-gesture `pointerMove` +
 * `compute`): `none` below the 3 px threshold, `first` on the move that
 * crosses it, `move` afterwards.
 */
export function advanceDragGesture(
  drag: DragGesture,
  clientX: number,
  clientY: number
): "none" | "first" | "move" {
  const dx = clientX - drag.last[0];
  const dy = clientY - drag.last[1];
  drag.last = [clientX, clientY];
  drag.movement[0] += dx;
  drag.movement[1] += dy;
  if (drag.active) {
    drag.distance[0] += Math.abs(dx);
    drag.distance[1] += Math.abs(dy);
  }
  if (
    !drag.intentional &&
    (Math.abs(drag.movement[0]) >= DRAG_THRESHOLD_PX ||
      Math.abs(drag.movement[1]) >= DRAG_THRESHOLD_PX)
  ) {
    drag.intentional = true;
  }
  if (!(drag.intentional && drag.active)) {
    return "none";
  }
  const first = !drag.started;
  drag.started = true;
  return first ? "first" : "move";
}

/** Distance and midpoint (client px) of the first two pinch pointers. */
function pinchPayload(
  pointers: PinchGesture["pointers"]
): { distance: number; origin: [number, number] } | null {
  const [a, b] = Array.from(pointers.values());
  if (!(a && b)) {
    return null;
  }
  return {
    distance: Math.hypot(b.clientX - a.clientX, b.clientY - a.clientY),
    origin: [(b.clientX + a.clientX) / 2, (b.clientY + a.clientY) / 2],
  };
}

function supportsGestureEvents(): boolean {
  return (
    typeof window !== "undefined" &&
    !("ontouchstart" in window) &&
    "GestureEvent" in window
  );
}

export function useChoroplethZoomState<E extends Element>({
  width,
  height,
  initialTransformMatrix = DEFAULT_INITIAL,
  scaleXMin = 0,
  scaleXMax = Number.POSITIVE_INFINITY,
  scaleYMin = 0,
  scaleYMax = Number.POSITIVE_INFINITY,
  wheelDelta = defaultWheelDelta,
  pinchDelta = defaultPinchDelta,
  constrain,
}: ChoroplethZoomOptions): ZoomInstance<E> {
  // --- visx Zoom.js -------------------------------------------------------

  const containerRef = useRef<E | null>(null);
  const matrixStateRef = useRef<TransformMatrix>(initialTransformMatrix);
  const [transformMatrix, setTransformMatrixState] = useState(
    initialTransformMatrix
  );
  const [isDragging, setIsDragging] = useState(false);
  const [startTranslate, setStartTranslate] = useState<Translate | undefined>(
    undefined
  );
  const [startPoint, setStartPoint] = useState<Point | undefined>(undefined);

  const defaultConstrain = useCallback(
    (next: TransformMatrix, prev: TransformMatrix) =>
      constrain
        ? constrain(next, prev)
        : constrainScale(next, prev, {
            scaleXMin,
            scaleXMax,
            scaleYMin,
            scaleYMax,
          }),
    [constrain, scaleXMin, scaleXMax, scaleYMin, scaleYMax]
  );

  const setTransformMatrix = useCallback(
    (next: TransformMatrix) => {
      setTransformMatrixState((prev) => {
        const updated = defaultConstrain(next, prev);
        matrixStateRef.current = updated;
        return updated;
      });
    },
    [defaultConstrain]
  );

  const applyToPoint = useCallback(
    ({ x, y }: Point) => applyMatrixToPoint(transformMatrix, { x, y }),
    [transformMatrix]
  );
  const applyInverseToPoint = useCallback(
    ({ x, y }: Point) => applyInverseMatrixToPoint(transformMatrix, { x, y }),
    [transformMatrix]
  );
  const reset = useCallback(() => {
    setTransformMatrix(initialTransformMatrix);
  }, [initialTransformMatrix, setTransformMatrix]);

  const scale = useCallback(
    ({ scaleX, scaleY, point }: ScaleSignature) => {
      // visx reads the ref, not state: the wheel listener has no fresh state.
      setTransformMatrix(
        scaleMatrixAroundPoint(
          matrixStateRef.current,
          { scaleX, scaleY, point },
          width,
          height
        )
      );
      if (isDragging) {
        const { translateX, translateY } = matrixStateRef.current;
        setStartPoint(point);
        setStartTranslate({ translateX, translateY });
      }
    },
    [height, width, isDragging, setTransformMatrix]
  );

  const translate = useCallback(
    ({ translateX, translateY }: Translate) => {
      setTransformMatrix(
        composeMatrices(
          transformMatrix,
          translateMatrix(translateX, translateY)
        )
      );
    },
    [setTransformMatrix, transformMatrix]
  );
  const setTranslate = useCallback(
    ({ translateX, translateY }: Translate) => {
      setTransformMatrix({ ...transformMatrix, translateX, translateY });
    },
    [setTransformMatrix, transformMatrix]
  );
  const translateTo = useCallback(
    ({ x, y }: Point) => {
      const point = applyInverseMatrixToPoint(transformMatrix, { x, y });
      setTranslate({ translateX: point.x, translateY: point.y });
    },
    [setTranslate, transformMatrix]
  );
  const invert = useCallback(
    () => inverseMatrix(transformMatrix),
    [transformMatrix]
  );
  const toStringInvert = useCallback(() => matrixToString(invert()), [invert]);

  const dragStart = useCallback(
    (event: LocalPointEvent) => {
      const { translateX, translateY } = transformMatrix;
      setStartPoint(localPoint(event) || undefined);
      setStartTranslate({ translateX, translateY });
      setIsDragging(true);
    },
    [transformMatrix]
  );
  const dragMove = useCallback(
    (
      event: LocalPointEvent,
      options?: { offsetX?: number; offsetY?: number }
    ) => {
      if (!(isDragging && startPoint && startTranslate)) {
        return;
      }
      const currentPoint = localPoint(event);
      const dx = currentPoint
        ? -(startPoint.x - currentPoint.x)
        : -startPoint.x;
      const dy = currentPoint
        ? -(startPoint.y - currentPoint.y)
        : -startPoint.y;
      let translateX = startTranslate.translateX + dx;
      if (options?.offsetX) {
        translateX += options.offsetX ?? 0;
      }
      let translateY = startTranslate.translateY + dy;
      if (options?.offsetY) {
        translateY += options.offsetY ?? 0;
      }
      setTranslate({ translateX, translateY });
    },
    [isDragging, setTranslate, startPoint, startTranslate]
  );
  const dragEnd = useCallback(() => {
    setStartPoint(undefined);
    setStartTranslate(undefined);
    setIsDragging(false);
  }, []);

  const handleWheel = useCallback(
    (event: ReactWheelEvent | WheelEvent) => {
      event.preventDefault();
      const point = localPoint(event as LocalPointEvent) || undefined;
      const { scaleX, scaleY } = wheelDelta(event);
      scale({ scaleX, scaleY, point });
    },
    [scale, wheelDelta]
  );

  const handlePinch = useCallback(
    (state: PinchHandlerState) => {
      const {
        origin: [ox, oy],
        memo,
      } = state;
      let currentMemo = memo;
      if (containerRef.current) {
        const { top, left } =
          currentMemo ?? containerRef.current.getBoundingClientRect();
        if (!currentMemo) {
          currentMemo = { top, left };
        }
        const { scaleX, scaleY } = pinchDelta(state);
        scale({ scaleX, scaleY, point: { x: ox - left, y: oy - top } });
      }
      return currentMemo;
    },
    [scale, pinchDelta]
  );

  const toMatrixString = useCallback(
    () => matrixToString(transformMatrix),
    [transformMatrix]
  );
  const center = useCallback(() => {
    const centerPoint = { x: width / 2, y: height / 2 };
    const inverseCentroid = applyInverseToPoint(centerPoint);
    translate({
      translateX: inverseCentroid.x - centerPoint.x,
      translateY: inverseCentroid.y - centerPoint.y,
    });
  }, [height, width, applyInverseToPoint, translate]);
  const clear = useCallback(() => {
    setTransformMatrix(identityMatrix());
  }, [setTransformMatrix]);

  // use-gesture applies the latest render's handlers during render.
  const api = { dragStart, dragMove, dragEnd, handleWheel, handlePinch };
  const apiRef = useRef(api);
  apiRef.current = api;

  // --- gestures (use-gesture drag / wheel / pinch engines) ----------------

  const pointerIdsRef = useRef(new Set<number>());
  const dragRef = useRef<DragGesture | null>(null);
  const tapRef = useRef(false);
  /** use-gesture drag `state.last`: survives into the next gesture. */
  const dragLastRef = useRef(false);
  const pinchRef = useRef<PinchGesture>({
    active: false,
    source: null,
    offset: 1,
    lastOffset: 1,
    movement: 0,
    initialDistance: 0,
    origin: [0, 0],
    memo: undefined,
    pointers: new Map(),
  });
  const wheelPinchTimerRef = useRef<ReturnType<typeof setTimeout> | null>(null);
  const cancelTimerRef = useRef<ReturnType<typeof setTimeout> | null>(null);

  /** One pinch handler call (visx `handlePinch`); keeps its memo. */
  const emitPinch = useCallback(() => {
    const pinch = pinchRef.current;
    pinch.memo = apiRef.current.handlePinch({
      offset: [pinch.offset, 0],
      lastOffset: [pinch.lastOffset, 0],
      origin: pinch.origin,
      memo: pinch.memo,
    });
  }, []);

  const startPinch = useCallback((source: PinchGesture["source"]) => {
    const pinch = pinchRef.current;
    pinch.active = true;
    pinch.source = source;
    pinch.lastOffset = pinch.offset;
    pinch.movement = 0;
    pinch.memo = undefined;
  }, []);

  const endPinch = useCallback(() => {
    const pinch = pinchRef.current;
    pinch.active = false;
    pinch.source = null;
    emitPinch();
  }, [emitPinch]);

  /** use-gesture drag handler: onDragStart (first), onDrag, onDragEnd (last). */
  const emitDrag = useCallback(
    (event: PointerEvent, first: boolean, last: boolean) => {
      const handlers = apiRef.current;
      const drag = dragRef.current;
      if (first) {
        handlers.dragStart(event);
      }
      if (pinchRef.current.active) {
        // visx: `cancel(); dragEnd();`. The cancel re-emits on a timeout.
        if (drag?.active) {
          drag.active = false;
          drag.pointerActive = false;
          cancelTimerRef.current = setTimeout(() => {
            cancelTimerRef.current = null;
            dragLastRef.current = true;
            const latest = apiRef.current;
            if (pinchRef.current.active) {
              latest.dragEnd();
            } else if (drag.event) {
              latest.dragMove(drag.event);
            }
            latest.dragEnd();
          }, 0);
        }
        handlers.dragEnd();
      } else {
        handlers.dragMove(event);
      }
      if (last) {
        handlers.dragEnd();
      }
    },
    []
  );

  const dragPointerDown = useCallback((event: PointerEvent) => {
    const drag = dragRef.current;
    if (
      !(event.buttons == null || event.buttons === 1) ||
      (pointerIdsRef.current.size > 1 && drag?.pointerActive)
    ) {
      return;
    }
    // use-gesture resets `tap` when a drag starts.
    tapRef.current = false;
    dragRef.current = createDragGesture(event);
  }, []);

  const dragPointerMove = useCallback(
    (event: PointerEvent) => {
      const drag = dragRef.current;
      if (!(drag?.pointerActive && event.pointerId === drag.pointerId)) {
        return;
      }
      const step = advanceDragGesture(drag, event.clientX, event.clientY);
      if (step === "none") {
        return;
      }
      drag.event = event;
      if (step === "first") {
        dragLastRef.current = false;
      }
      emitDrag(event, step === "first", false);
    },
    [emitDrag]
  );

  const dragPointerEnd = useCallback(
    (event: PointerEvent) => {
      const drag = dragRef.current;
      if (
        !(
          drag?.active &&
          drag.pointerActive &&
          event.pointerId === drag.pointerId
        )
      ) {
        return;
      }
      drag.pointerActive = false;
      drag.active = false;
      tapRef.current =
        drag.distance[0] <= DRAG_THRESHOLD_PX &&
        drag.distance[1] <= DRAG_THRESHOLD_PX;
      if (drag.started) {
        drag.event = event;
        dragLastRef.current = true;
        emitDrag(event, false, true);
      } else if (tapRef.current) {
        // A tap still reaches the handlers (filterTaps); `last` is whatever
        // the previous drag left, so a tap after a drag calls dragEnd.
        emitDrag(event, false, dragLastRef.current);
      }
    },
    [emitDrag]
  );

  const pinchPointerDown = useCallback(
    (event: PointerEvent) => {
      // Desktop Safari pinches through gesture events instead.
      if (supportsGestureEvents()) {
        return;
      }
      const pinch = pinchRef.current;
      const ids = pointerIdsRef.current;
      if (
        pinch.active &&
        Array.from(pinch.pointers.keys()).every((id) => ids.has(id))
      ) {
        return;
      }
      if (pinch.pointers.size < 2) {
        pinch.pointers.set(event.pointerId, {
          clientX: event.clientX,
          clientY: event.clientY,
        });
      }
      const payload = pinchPayload(pinch.pointers);
      if (!payload) {
        return;
      }
      if (!pinch.active) {
        startPinch("pointer");
      }
      pinch.initialDistance = payload.distance;
      pinch.origin = payload.origin;
      // Movement is 0 at the start, so offset === lastOffset (a 1.1 step).
      pinch.offset = pinch.lastOffset;
      emitPinch();
    },
    [emitPinch, startPinch]
  );

  const pinchPointerMove = useCallback(
    (event: PointerEvent) => {
      const pinch = pinchRef.current;
      if (!pinch.pointers.has(event.pointerId)) {
        return;
      }
      pinch.pointers.set(event.pointerId, {
        clientX: event.clientX,
        clientY: event.clientY,
      });
      const payload = pinchPayload(pinch.pointers);
      if (!(pinch.active && pinch.source === "pointer" && payload)) {
        return;
      }
      pinch.origin = payload.origin;
      const movement = payload.distance / pinch.initialDistance - 1;
      pinch.offset = (1 + movement) * pinch.lastOffset;
      emitPinch();
    },
    [emitPinch]
  );

  const pinchPointerEnd = useCallback(
    (event: PointerEvent) => {
      const pinch = pinchRef.current;
      if (!pinch.pointers.delete(event.pointerId)) {
        return;
      }
      if (
        pinch.active &&
        pinch.source === "pointer" &&
        pinch.pointers.size < 2
      ) {
        endPinch();
      }
    },
    [endPinch]
  );

  const handlePointerDown = useCallback(
    (event: PointerEvent) => {
      if (!(event.buttons == null || event.buttons % 2 === 1)) {
        return;
      }
      pointerIdsRef.current.add(event.pointerId);
      try {
        (event.target as Element).setPointerCapture(event.pointerId);
      } catch {
        // Not capturable (synthetic event).
      }
      dragPointerDown(event);
      pinchPointerDown(event);
    },
    [dragPointerDown, pinchPointerDown]
  );

  const handlePointerMove = useCallback(
    (event: PointerEvent) => {
      dragPointerMove(event);
      pinchPointerMove(event);
    },
    [dragPointerMove, pinchPointerMove]
  );

  const handlePointerEnd = useCallback(
    (event: PointerEvent) => {
      if (event.type === "pointerup" || event.type === "pointercancel") {
        pointerIdsRef.current.delete(event.pointerId);
      }
      const target = event.target as Element;
      try {
        if (target.hasPointerCapture?.(event.pointerId)) {
          target.releasePointerCapture(event.pointerId);
        }
      } catch {
        // Detached.
      }
      dragPointerEnd(event);
      pinchPointerEnd(event);
    },
    [dragPointerEnd, pinchPointerEnd]
  );

  const handleWheelEvent = useCallback(
    (event: WheelEvent) => {
      // use-gesture's wheel recogniser runs before the pinch one, so the first
      // ctrl+wheel of a pinch reaches both handlers in the same event.
      if (!pinchRef.current.active) {
        apiRef.current.handleWheel(event);
      }
      if (!event.ctrlKey) {
        return;
      }
      const pinch = pinchRef.current;
      if (!pinch.active) {
        startPinch("wheel");
      }
      if (event.cancelable) {
        event.preventDefault();
      }
      pinch.movement +=
        (-wheelDeltaYPixels(event) / PINCH_WHEEL_RATIO) * pinch.offset;
      pinch.origin = [event.clientX, event.clientY];
      pinch.offset = pinch.movement + pinch.lastOffset;
      emitPinch();
      if (wheelPinchTimerRef.current) {
        clearTimeout(wheelPinchTimerRef.current);
      }
      wheelPinchTimerRef.current = setTimeout(() => {
        wheelPinchTimerRef.current = null;
        if (pinchRef.current.active) {
          endPinch();
        }
      }, WHEEL_END_MS);
    },
    [emitPinch, endPinch, startPinch]
  );

  const handleGesture = useCallback(
    (event: Event) => {
      const gesture = event as Event & {
        scale: number;
        clientX: number;
        clientY: number;
      };
      const pinch = pinchRef.current;
      if (event.type === "gestureend") {
        if (pinch.active) {
          endPinch();
        }
        return;
      }
      if (event.cancelable) {
        event.preventDefault();
      }
      if (event.type === "gesturestart") {
        if (pinch.active) {
          return;
        }
        startPinch("gesture");
        pinch.origin = [gesture.clientX, gesture.clientY];
        pinch.offset = pinch.lastOffset;
        emitPinch();
        return;
      }
      if (!pinch.active) {
        return;
      }
      pinch.origin = [gesture.clientX, gesture.clientY];
      pinch.offset = (1 + (gesture.scale - 1)) * pinch.lastOffset;
      emitPinch();
    },
    [emitPinch, endPinch, startPinch]
  );

  const handleClickCapture = useCallback((event: MouseEvent) => {
    if (!tapRef.current && event.detail > 0) {
      event.preventDefault();
      event.stopPropagation();
    }
  }, []);

  // Bind native (non-passive) listeners to the container; rebind if the
  // element is replaced.
  const handlersRef = useRef({
    handlePointerDown,
    handlePointerMove,
    handlePointerEnd,
    handleWheelEvent,
    handleGesture,
    handleClickCapture,
  });
  const boundRef = useRef<{ element: E; cleanup: () => void } | null>(null);
  useEffect(() => {
    const element = containerRef.current;
    if (boundRef.current?.element === element) {
      return;
    }
    boundRef.current?.cleanup();
    boundRef.current = null;
    if (!element) {
      return;
    }
    const handlers = handlersRef.current;
    const types = [
      "pointerdown",
      "pointermove",
      "pointerup",
      "pointercancel",
      "lostpointercapture",
      "wheel",
      ...(supportsGestureEvents()
        ? ["gesturestart", "gesturechange", "gestureend"]
        : []),
    ];
    const listener = (event: Event) => {
      if (event.type === "pointerdown") {
        handlers.handlePointerDown(event as PointerEvent);
      } else if (event.type === "pointermove") {
        handlers.handlePointerMove(event as PointerEvent);
      } else if (event.type === "wheel") {
        handlers.handleWheelEvent(event as WheelEvent);
      } else if (event.type.startsWith("gesture")) {
        handlers.handleGesture(event);
      } else {
        handlers.handlePointerEnd(event as PointerEvent);
      }
    };
    const clickListener = (event: Event) =>
      handlers.handleClickCapture(event as MouseEvent);
    for (const type of types) {
      element.addEventListener(type, listener, { passive: false });
    }
    element.addEventListener("click", clickListener, {
      capture: true,
      passive: false,
    });
    boundRef.current = {
      element,
      cleanup: () => {
        for (const type of types) {
          element.removeEventListener(type, listener);
        }
        element.removeEventListener("click", clickListener, true);
      },
    };
  });
  useEffect(
    () => () => {
      boundRef.current?.cleanup();
      boundRef.current = null;
      for (const timer of [wheelPinchTimerRef, cancelTimerRef]) {
        if (timer.current) {
          clearTimeout(timer.current);
        }
      }
    },
    []
  );

  // A fresh object every render, like visx's `zoom`.
  return {
    initialTransformMatrix,
    transformMatrix,
    isDragging,
    center,
    clear,
    scale,
    translate,
    translateTo,
    setTranslate,
    setTransformMatrix,
    reset,
    handleWheel,
    dragEnd,
    dragMove,
    dragStart,
    toString: toMatrixString,
    invert,
    toStringInvert,
    applyToPoint,
    applyInverseToPoint,
    containerRef,
  };
}

"use client";

import type { Feature, FeatureCollection, GeoJSON, Geometry } from "geojson";
import type { Transition } from "motion/react";
import {
  createContext,
  type Dispatch,
  type RefObject,
  type SetStateAction,
  useContext,
  useMemo,
  useState,
} from "react";
import type { ZoomInstance } from "./use-choropleth-zoom-state";

export type { ZoomInstance } from "./use-choropleth-zoom-state";

// Zoom context to share zoom controls with child components
interface ChoroplethZoomContextValue {
  zoom: ZoomInstance<SVGSVGElement> | null;
}

export const ChoroplethZoomContext = createContext<ChoroplethZoomContextValue>({
  zoom: null,
});

export function useChoroplethZoom() {
  return useContext(ChoroplethZoomContext);
}

export interface Margin {
  top: number;
  right: number;
  bottom: number;
  left: number;
}

export interface ChoroplethFeatureProperties {
  name?: string;
  id?: string | number;
  [key: string]: unknown;
}

export type ChoroplethFeature = Feature<Geometry, ChoroplethFeatureProperties>;

export interface ChoroplethTooltipData {
  featureIndex: number;
  x: number;
  y: number;
  feature: ChoroplethFeature;
}

/** Hovered or focused `ChoroplethMarker`, shown by `ChoroplethTooltip`. */
export interface ChoroplethMarkerTooltipData {
  label: string;
  coordinates: [number, number];
}

export interface ChoroplethInteractionContextValue {
  hoveredFeatureIndex: number | null;
  setHoveredFeatureIndex: (index: number | null) => void;
  tooltipData: ChoroplethTooltipData | null;
  setTooltipData: Dispatch<SetStateAction<ChoroplethTooltipData | null>>;
  markerTooltip?: ChoroplethMarkerTooltipData | null;
  setMarkerTooltip?: (marker: ChoroplethMarkerTooltipData | null) => void;
}

export interface ChoroplethStableContextValue {
  // Geo data
  features: ChoroplethFeature[];
  featureCollection: FeatureCollection<Geometry, ChoroplethFeatureProperties>;

  /** Precomputed SVG path strings — one per feature index. */
  featurePaths: readonly (string | null)[];

  // Projection function (returns path string)
  pathGenerator: (feature: ChoroplethFeature) => string | undefined;

  // Raw path function for graticule (accepts any geo object)
  rawPathGenerator: (geo: GeoJSON) => string | null;

  // Project geo coordinates to screen coordinates
  projectPoint: (coords: [number, number]) => [number, number] | null;

  // Dimensions
  width: number;
  height: number;
  innerWidth: number;
  innerHeight: number;
  margin: Margin;

  containerRef: RefObject<HTMLDivElement | null>;

  // Animation
  isLoaded: boolean;
  animationDuration: number;
  enterTransition?: Transition;
  revealEpoch: number;
}

export type ChoroplethContextValue = ChoroplethStableContextValue &
  ChoroplethInteractionContextValue;

const ChoroplethStableContext =
  createContext<ChoroplethStableContextValue | null>(null);
const ChoroplethInteractionContext =
  createContext<ChoroplethInteractionContextValue | null>(null);

export function ChoroplethStableProvider({
  children,
  value,
}: {
  children: React.ReactNode;
  value: ChoroplethStableContextValue;
}) {
  return (
    <ChoroplethStableContext.Provider value={value}>
      {children}
    </ChoroplethStableContext.Provider>
  );
}

export function ChoroplethInteractionShell({
  children,
}: {
  children: React.ReactNode;
}) {
  const [hoveredFeatureIndex, setHoveredFeatureIndex] = useState<number | null>(
    null
  );
  const [tooltipData, setTooltipData] = useState<ChoroplethTooltipData | null>(
    null
  );
  const [markerTooltip, setMarkerTooltip] =
    useState<ChoroplethMarkerTooltipData | null>(null);

  const interaction = useMemo<ChoroplethInteractionContextValue>(
    () => ({
      hoveredFeatureIndex,
      setHoveredFeatureIndex,
      tooltipData,
      setTooltipData,
      markerTooltip,
      setMarkerTooltip,
    }),
    [hoveredFeatureIndex, tooltipData, markerTooltip]
  );

  return (
    <ChoroplethInteractionContext.Provider value={interaction}>
      {children}
    </ChoroplethInteractionContext.Provider>
  );
}

export function ChoroplethProvider({
  children,
  value,
}: {
  children: React.ReactNode;
  value: ChoroplethContextValue;
}) {
  const stable = useMemo<ChoroplethStableContextValue>(
    () => ({
      features: value.features,
      featureCollection: value.featureCollection,
      featurePaths: value.featurePaths,
      pathGenerator: value.pathGenerator,
      rawPathGenerator: value.rawPathGenerator,
      projectPoint: value.projectPoint,
      width: value.width,
      height: value.height,
      innerWidth: value.innerWidth,
      innerHeight: value.innerHeight,
      margin: value.margin,
      containerRef: value.containerRef,
      isLoaded: value.isLoaded,
      animationDuration: value.animationDuration,
      enterTransition: value.enterTransition,
      revealEpoch: value.revealEpoch,
    }),
    [
      value.features,
      value.featureCollection,
      value.featurePaths,
      value.pathGenerator,
      value.rawPathGenerator,
      value.projectPoint,
      value.width,
      value.height,
      value.innerWidth,
      value.innerHeight,
      value.margin,
      value.containerRef,
      value.isLoaded,
      value.animationDuration,
      value.enterTransition,
      value.revealEpoch,
    ]
  );

  const interaction = useMemo<ChoroplethInteractionContextValue>(
    () => ({
      hoveredFeatureIndex: value.hoveredFeatureIndex,
      setHoveredFeatureIndex: value.setHoveredFeatureIndex,
      tooltipData: value.tooltipData,
      setTooltipData: value.setTooltipData,
      markerTooltip: value.markerTooltip,
      setMarkerTooltip: value.setMarkerTooltip,
    }),
    [
      value.markerTooltip,
      value.setMarkerTooltip,
      value.hoveredFeatureIndex,
      value.setHoveredFeatureIndex,
      value.tooltipData,
      value.setTooltipData,
    ]
  );

  return (
    <ChoroplethStableProvider value={stable}>
      <ChoroplethInteractionContext.Provider value={interaction}>
        {children}
      </ChoroplethInteractionContext.Provider>
    </ChoroplethStableProvider>
  );
}

export function useChoroplethStable(): ChoroplethStableContextValue {
  const context = useContext(ChoroplethStableContext);
  if (!context) {
    throw new Error(
      "useChoroplethStable must be used within a ChoroplethProvider"
    );
  }
  return context;
}

export function useChoroplethInteraction(): ChoroplethInteractionContextValue {
  const context = useContext(ChoroplethInteractionContext);
  if (!context) {
    throw new Error(
      "useChoroplethInteraction must be used within a ChoroplethProvider"
    );
  }
  return context;
}

export function useChoropleth(): ChoroplethContextValue {
  return { ...useChoroplethStable(), ...useChoroplethInteraction() };
}

