"use client";

import { geoCentroid } from "d3-geo";
import { m, useTransform } from "motion/react";
import { memo, useCallback, useMemo } from "react";
import { useEnterComplete } from "../use-enter-complete";
import { useMountProgress } from "../use-mount-progress";
import { useChoroplethCamera } from "./choropleth-camera";
import {
  type ChoroplethFeature as ChoroplethFeatureType,
  defaultChoroplethColors,
  useChoroplethInteraction,
  useChoroplethStable,
} from "./choropleth-context";

export interface ChoroplethFeatureProps {
  fill?: string;
  stroke?: string;
  strokeWidth?: number;
  fadedOpacity?: number;
  getFeatureColor?: (feature: ChoroplethFeatureType, index: number) => string;
  patterns?: React.ReactNode;
  getFeaturePattern?: (
    feature: ChoroplethFeatureType,
    index: number
  ) => string | null | undefined;
}

interface FeatureRecord {
  index: number;
  path: string;
  fill: string;
  feature: ChoroplethFeatureType;
  centroid: { x: number; y: number } | null;
}

function resolveFeatureFill(
  feature: ChoroplethFeatureType,
  index: number,
  fill: string | undefined,
  getFeatureColor: ChoroplethFeatureProps["getFeatureColor"],
  getFeaturePattern: ChoroplethFeatureProps["getFeaturePattern"]
): string {
  const patternId = getFeaturePattern?.(feature, index);
  if (patternId) {
    return `url(#${patternId})`;
  }
  if (fill) {
    return fill;
  }
  if (getFeatureColor) {
    return getFeatureColor(feature, index);
  }
  return (
    defaultChoroplethColors[index % defaultChoroplethColors.length] ??
    "var(--chart-1)"
  );
}

const StaticFeatureLayer = memo(function StaticFeatureLayer({
  records,
  stroke,
  strokeWidth,
  baseOpacity,
  dimOpacity,
  hoveredIndex,
  focusedIndex,
  onFeatureEnter,
  onFeatureLeave,
  onFeatureClick,
}: {
  records: FeatureRecord[];
  stroke: string;
  strokeWidth: number;
  baseOpacity: number;
  dimOpacity: number;
  hoveredIndex: number | null;
  /** Region the camera is focused on — never dimmed. */
  focusedIndex: number | null;
  onFeatureEnter: (record: FeatureRecord) => void;
  onFeatureLeave: () => void;
  onFeatureClick: (index: number) => void;
}) {
  const isDimmed = hoveredIndex !== null;

  if (!isDimmed) {
    return (
      <g opacity={baseOpacity}>
        {records.map((record) => (
          // biome-ignore lint/a11y/noStaticElementInteractions: SVG path used as hover hitbox
          <path
            className="cursor-pointer"
            d={record.path}
            fill={record.fill}
            key={`base-${record.index}`}
            onClick={() => onFeatureClick(record.index)}
            onMouseEnter={() => onFeatureEnter(record)}
            onMouseLeave={onFeatureLeave}
            stroke={stroke}
            strokeWidth={strokeWidth}
          />
        ))}
      </g>
    );
  }

  const isLit = (index: number) =>
    index === hoveredIndex || index === focusedIndex;
  // Focused region first so a hovered neighbour draws on top of it.
  const highlighted = records
    .filter((record) => isLit(record.index))
    .sort((a) => (a.index === hoveredIndex ? 1 : -1));

  return (
    <>
      <g opacity={dimOpacity} style={{ transition: "opacity 0.18s ease-out" }}>
        {records
          .filter((record) => !isLit(record.index))
          .map((record) => (
            // biome-ignore lint/a11y/noStaticElementInteractions: SVG path used as hover hitbox
            <path
              className="cursor-pointer"
              d={record.path}
              fill={record.fill}
              key={`base-${record.index}`}
              onClick={() => onFeatureClick(record.index)}
              onMouseEnter={() => onFeatureEnter(record)}
              onMouseLeave={onFeatureLeave}
              stroke={stroke}
              strokeWidth={strokeWidth}
            />
          ))}
      </g>
      {highlighted.map((record) => (
        // biome-ignore lint/a11y/noStaticElementInteractions: SVG path used as hover hitbox
        <path
          className="cursor-pointer"
          d={record.path}
          fill={record.fill}
          key={`highlight-${record.index}`}
          onClick={() => onFeatureClick(record.index)}
          onMouseEnter={() => onFeatureEnter(record)}
          onMouseLeave={onFeatureLeave}
          opacity={1}
          stroke={stroke}
          strokeWidth={strokeWidth}
          style={{ transition: "opacity 0.18s ease-out" }}
        />
      ))}
    </>
  );
});

const EnterFeatureLayer = memo(function EnterFeatureLayer({
  records,
  stroke,
  strokeWidth,
  baseOpacity,
  dimOpacity,
  hoveredIndex,
  focusedIndex,
  onFeatureEnter,
  onFeatureLeave,
  onFeatureClick,
  revealEpoch,
}: {
  records: FeatureRecord[];
  stroke: string;
  strokeWidth: number;
  baseOpacity: number;
  dimOpacity: number;
  hoveredIndex: number | null;
  /** Region the camera is focused on — never dimmed. */
  focusedIndex: number | null;
  onFeatureEnter: (record: FeatureRecord) => void;
  onFeatureLeave: () => void;
  onFeatureClick: (index: number) => void;
  revealEpoch: number;
}) {
  const { enterTransition, animationDuration } = useChoroplethStable();
  const mountProgress = useMountProgress(
    enterTransition,
    0,
    `choropleth-layer-${revealEpoch}`
  );
  const enterComplete = useEnterComplete(mountProgress);
  const layerOpacity = useTransform(mountProgress, (t) => t * baseOpacity);

  if (enterComplete) {
    return (
      <StaticFeatureLayer
        baseOpacity={baseOpacity}
        dimOpacity={dimOpacity}
        focusedIndex={focusedIndex}
        hoveredIndex={hoveredIndex}
        onFeatureClick={onFeatureClick}
        onFeatureEnter={onFeatureEnter}
        onFeatureLeave={onFeatureLeave}
        records={records}
        stroke={stroke}
        strokeWidth={strokeWidth}
      />
    );
  }

  return (
    <m.g
      key={`enter-${revealEpoch}`}
      opacity={layerOpacity}
      transition={{
        duration: animationDuration / 1000,
        ease: "easeOut",
      }}
    >
      {records.map((record) => (
        // biome-ignore lint/a11y/noStaticElementInteractions: SVG path used as hover hitbox
        <path
          className="cursor-pointer"
          d={record.path}
          fill={record.fill}
          key={`enter-${record.index}`}
          onClick={() => onFeatureClick(record.index)}
          onMouseEnter={() => onFeatureEnter(record)}
          onMouseLeave={onFeatureLeave}
          stroke={stroke}
          strokeWidth={strokeWidth}
        />
      ))}
    </m.g>
  );
});

export const ChoroplethFeature = memo(function ChoroplethFeature({
  fill,
  stroke = "var(--background)",
  strokeWidth = 0.5,
  fadedOpacity = 0.4,
  getFeatureColor,
  patterns,
  getFeaturePattern,
}: ChoroplethFeatureProps) {
  const {
    features,
    featurePaths,
    pathGenerator,
    projectPoint,
    isLoaded,
    revealEpoch,
    width,
    height,
  } = useChoroplethStable();
  const { hoveredFeatureIndex, setHoveredFeatureIndex, setTooltipData } =
    useChoroplethInteraction();

  const featureCentroids = useMemo(() => {
    return features.map((feature) => {
      try {
        const centroid = geoCentroid(feature);
        if (
          centroid &&
          !Number.isNaN(centroid[0]) &&
          !Number.isNaN(centroid[1])
        ) {
          const projected = projectPoint(centroid as [number, number]);
          if (projected) {
            const padding = 60;
            return {
              x: Math.max(padding, Math.min(width - padding, projected[0])),
              y: Math.max(padding, Math.min(height - padding, projected[1])),
            };
          }
        }
      } catch {
        // Some geometries may not have valid centroids
      }
      return null;
    });
  }, [features, projectPoint, width, height]);

  const records = useMemo(() => {
    const items: FeatureRecord[] = [];
    for (let index = 0; index < features.length; index++) {
      const feature = features[index];
      if (!feature) {
        continue;
      }

      const path = featurePaths[index] ?? pathGenerator(feature);
      if (!path) {
        continue;
      }

      items.push({
        index,
        path,
        fill: resolveFeatureFill(
          feature,
          index,
          fill,
          getFeatureColor,
          getFeaturePattern
        ),
        feature,
        centroid: featureCentroids[index] ?? null,
      });
    }
    return items;
  }, [
    featureCentroids,
    featurePaths,
    features,
    fill,
    getFeatureColor,
    getFeaturePattern,
    pathGenerator,
  ]);

  const camera = useChoroplethCamera();
  const handleFeatureEnter = useCallback(
    (record: FeatureRecord) => {
      if (!camera.isHoverable(`feature:${record.index}`)) {
        return;
      }
      setHoveredFeatureIndex(record.index);
      setTooltipData({
        featureIndex: record.index,
        x: record.centroid?.x ?? width / 2,
        y: record.centroid?.y ?? height / 2,
        feature: record.feature,
      });
    },
    [camera, height, setHoveredFeatureIndex, setTooltipData, width]
  );

  const handleFeatureLeave = useCallback(() => {
    setHoveredFeatureIndex(null);
    setTooltipData(null);
  }, [setHoveredFeatureIndex, setTooltipData]);

  const handleFeatureClick = useCallback(
    (index: number) => {
      if (camera.enabled && !camera.wasDrag()) {
        camera.focusFeature(index);
      }
    },
    [camera]
  );

  const layerProps = {
    baseOpacity: 0.85,
    onFeatureClick: handleFeatureClick,
    dimOpacity: fadedOpacity,
    hoveredIndex: hoveredFeatureIndex,
    focusedIndex: camera.focusedFeatureIndex,
    onFeatureEnter: handleFeatureEnter,
    onFeatureLeave: handleFeatureLeave,
    records,
    stroke,
    strokeWidth,
  };

  return (
    <g className="choropleth-features">
      {patterns ? <defs>{patterns}</defs> : null}
      {isLoaded ? (
        <StaticFeatureLayer {...layerProps} />
      ) : (
        <EnterFeatureLayer {...layerProps} revealEpoch={revealEpoch} />
      )}
    </g>
  );
});

ChoroplethFeature.displayName = "ChoroplethFeature";

export default ChoroplethFeature;

"use client";

import { memo, useMemo } from "react";
import { useChoroplethCamera } from "./choropleth-camera";
import { useChoroplethStable } from "./choropleth-context";
import { graticulePath } from "./choropleth-projection";

export interface ChoroplethGraticuleProps {
  /** Stroke color for graticule lines. Default: rgba(255,255,255,0.1) */
  stroke?: string;
  /** Stroke width for graticule lines. Default: 0.5 */
  strokeWidth?: number;
  /** Step intervals for graticule lines [longitude, latitude] in degrees. Default: [10, 10] */
  step?: [number, number];
  /** Fade the lines out while the camera is focused on a region or marker. Default: true */
  hideOnFocus?: boolean;
}

export const ChoroplethGraticule = memo(function ChoroplethGraticule({
  stroke = "rgba(255,255,255,0.1)",
  strokeWidth = 0.5,
  step,
  hideOnFocus = true,
}: ChoroplethGraticuleProps) {
  const { rawPathGenerator } = useChoroplethStable();
  const { focusedKey } = useChoroplethCamera();
  const hidden = hideOnFocus && focusedKey !== null;
  const stepX = step?.[0];
  const stepY = step?.[1];

  const d = useMemo(
    () =>
      graticulePath(
        rawPathGenerator,
        stepX === undefined || stepY === undefined ? undefined : [stepX, stepY]
      ),
    [rawPathGenerator, stepX, stepY]
  );

  // Same markup as visx <Graticule>: a group wrapping one unfilled path.
  return (
    <g
      className="visx-group visx-geo-graticule"
      style={{ opacity: hidden ? 0 : 1, transition: "opacity 0.3s ease-out" }}
      transform="translate(0, 0)"
    >
      <path d={d} fill="none" stroke={stroke} strokeWidth={strokeWidth} />
    </g>
  );
});

ChoroplethGraticule.displayName = "ChoroplethGraticule";

export default ChoroplethGraticule;

"use client";

import { intFmt } from "../chart-formatters";
import { CursorTooltipBox } from "../tooltip/cursor-tooltip-box";
import { TooltipContent, type TooltipRow } from "../tooltip/tooltip-content";
import {
  TOOLTIP_HIDE_DELAY_MS,
  useDelayedTooltipData,
} from "../tooltip/use-delayed-tooltip-data";
import {
  type ChoroplethFeature,
  useChoroplethInteraction,
  useChoroplethStable,
} from "./choropleth-context";

export interface ChoroplethTooltipProps {
  /** Custom content renderer for feature tooltips */
  content?: (props: {
    feature: ChoroplethFeature;
    index: number;
  }) => React.ReactNode;
  /** Value formatter function */
  formatValue?: (value: number) => string;
  /** Get the display name for a feature. Default: uses feature.properties.name */
  getFeatureName?: (feature: ChoroplethFeature, index: number) => string;
  /** Get the value for a feature (for display in tooltip) */
  getFeatureValue?: (
    feature: ChoroplethFeature,
    index: number
  ) => number | undefined;
  /** Label for the value row. Default: "Value" */
  valueLabel?: string;
  /** Custom class name */
  className?: string;
  /** Inline styles for the tooltip panel (background, blur, etc.). */
  panelStyle?: React.CSSProperties;
  /**
   * Tooltip panel background color (CSS variable or color value).
   * Default: `var(--chart-tooltip-background)`.
   */
  backgroundColor?: string;
  /** Fade the panel out when hover ends. Default: true */
  exit?: boolean;
  /**
   * Grace period before hiding when the pointer leaves a feature (ms).
   * Bridges border gaps so the panel springs to the next feature instead of
   * fading out and back in. Default: `120`.
   */
  hideDelay?: number;
}

export function ChoroplethTooltip({
  content,
  formatValue = intFmt,
  getFeatureName,
  getFeatureValue,
  valueLabel = "Value",
  className = "",
  panelStyle,
  backgroundColor,
  exit = true,
  hideDelay = TOOLTIP_HIDE_DELAY_MS,
}: ChoroplethTooltipProps) {
  const { containerRef, features } = useChoroplethStable();
  const { tooltipData: hoverData, markerTooltip: hoverMarker } =
    useChoroplethInteraction();
  const tooltipData = useDelayedTooltipData(hoverData, 0, hideDelay);
  const marker = useDelayedTooltipData(hoverMarker ?? null, 0, hideDelay);

  const feature = tooltipData ? features[tooltipData.featureIndex] : undefined;

  let body: React.ReactNode = null;
  if (marker) {
    const [lon, lat] = marker.coordinates;
    body = (
      <TooltipContent
        rows={[
          {
            color: "var(--chart-foreground-muted)",
            label: "Location",
            value: `${lat.toFixed(2)}°, ${lon.toFixed(2)}°`,
          },
        ]}
        title={marker.label}
      />
    );
  } else if (tooltipData && feature) {
    const index = tooltipData.featureIndex;
    if (content) {
      body = content({ feature, index });
    } else {
      const featureName = getFeatureName
        ? getFeatureName(feature, index)
        : (feature.properties?.name ?? `Feature ${index}`);
      const value = getFeatureValue?.(feature, index);
      const rows: TooltipRow[] =
        value === undefined
          ? []
          : [
              {
                color: "var(--chart-1)",
                label: valueLabel,
                value: formatValue(value),
              },
            ];
      body = <TooltipContent rows={rows} title={featureName} />;
    }
  }

  // Always mounted so the panel can fade out; `visible` drives presence. The
  // panel follows the cursor (Motion values, no re-render per move); React
  // only re-renders here when the hovered feature changes.
  return (
    <CursorTooltipBox
      backgroundColor={backgroundColor}
      className={className}
      containerRef={containerRef}
      exit={exit}
      panelStyle={panelStyle}
      visible={Boolean(marker || (tooltipData && feature))}
    >
      {body}
    </CursorTooltipBox>
  );
}

ChoroplethTooltip.displayName = "ChoroplethTooltip";

export default ChoroplethTooltip;

"use client";

import { geoArea } from "d3-geo";
import type { Feature, Geometry, Polygon } from "geojson";
import {
  type AnimationPlaybackControls,
  animate,
  type MotionValue,
  useMotionValue,
  useReducedMotion,
} from "motion/react";
import {
  createContext,
  type RefObject,
  useCallback,
  useContext,
  useEffect,
  useMemo,
  useRef,
  useState,
} from "react";
import type { ChoroplethFeature } from "./choropleth-context";
import type { ChoroplethMercator } from "./choropleth-projection";

/** Side the camera looks from. `flat` is a straight-down view. */
export type ChoroplethViewSide = "west" | "flat" | "east";

export interface ChoroplethOverviewView {
  /**
   * Camera when zoomed out. `pointer` swings between west and east as the
   * pointer moves across the map. Default: `"flat"`
   */
  view?: ChoroplethViewSide | "pointer";
  /** Side-to-side rotation in degrees. Default: 18 */
  yaw?: number;
  /** Lean back in degrees (0 = top-down). Default: 0 */
  tilt?: number;
}

export interface ChoroplethFocusView {
  /**
   * Camera after clicking a region or marker. `auto` looks from the side of
   * the map the focused point is on. Default: same as `overview`
   */
  view?: ChoroplethViewSide | "auto";
  /** Side-to-side rotation in degrees. Default: 18 */
  yaw?: number;
  /** Lean back in degrees. Default: 0 */
  tilt?: number;
}

export interface ChoroplethPerspective {
  overview?: ChoroplethOverviewView;
  focus?: ChoroplethFocusView;
  /** CSS `perspective` distance in px — lower is more dramatic. Default: 1600 */
  depth?: number;
  /**
   * Fade the map out toward the chart's edges (% of width/height per side) so
   * the map dissolves into the frame instead of meeting it at a hard edge.
   * Default: 0
   */
  edgeFade?: number;
}

export interface ChoroplethZoomTransition {
  /** Duration in ms. Default: 700 */
  duration?: number;
  /** Cubic-bezier control points. Default: ease-in-out quint */
  ease?: readonly [number, number, number, number];
}

export const DEFAULT_CHOROPLETH_ZOOM_EASE = [0.83, 0, 0.17, 1] as const;
const DEFAULT_YAW = 18;
const POINTER_SPRING = { type: "spring", stiffness: 90, damping: 20 } as const;
const DRAG_CLICK_TOLERANCE = 5;

/** CSS variable carrying the camera scale, for counter-scaled overlays. */
export const CHOROPLETH_CAMERA_SCALE_VAR = "--choropleth-camera-k";

interface View {
  cx: number;
  cy: number;
  k: number;
}

export interface ChoroplethCameraApi {
  /** Click-to-zoom is on. */
  enabled: boolean;
  /** Key of the focused region (`feature:<index>`) or marker (`point:<key>`). */
  focusedKey: string | null;
  /** Index of the focused region, or null (nothing or a marker is focused). */
  focusedFeatureIndex: number | null;
  /** Camera scale cap (`focusMaxZoom`). */
  maxZoom: number;
  /**
   * Whether hovering `key` (`feature:<index>` / `point:<label>`) should react.
   * While zoomed in only the focused target does; the rest stay clickable.
   */
  isHoverable: (key: string) => boolean;
  focusFeature: (index: number) => void;
  focusPoint: (coordinates: [number, number], key: string) => void;
  reset: () => void;
  /** True when the last pointer press moved enough to count as a drag. */
  wasDrag: () => boolean;
}

const noop = () => undefined;

export const ChoroplethCameraContext = createContext<ChoroplethCameraApi>({
  enabled: false,
  focusedKey: null,
  focusedFeatureIndex: null,
  maxZoom: 1,
  isHoverable: () => true,
  focusFeature: noop,
  focusPoint: noop,
  reset: noop,
  wasDrag: () => false,
});

export function useChoroplethCamera(): ChoroplethCameraApi {
  return useContext(ChoroplethCameraContext);
}

/** Largest polygon of a feature, so France frames France, not French Guiana. */
function mainland(feature: ChoroplethFeature): Feature<Geometry> {
  const geometry = feature.geometry;
  if (geometry?.type !== "MultiPolygon") {
    return feature;
  }
  let best: Polygon | null = null;
  let bestArea = -1;
  for (const coordinates of geometry.coordinates) {
    const polygon: Polygon = { type: "Polygon", coordinates };
    const area = geoArea(polygon);
    if (area > bestArea) {
      bestArea = area;
      best = polygon;
    }
  }
  return best ? { ...feature, geometry: best } : feature;
}

function signedYaw(side: ChoroplethViewSide, yaw: number) {
  if (side === "flat") {
    return 0;
  }
  // Looking from the east brings the east edge toward the viewer.
  return side === "east" ? -yaw : yaw;
}

interface UseCameraOptions {
  width: number;
  height: number;
  mercator: ChoroplethMercator;
  features: readonly ChoroplethFeature[];
  clickToZoom: boolean;
  focusMaxZoom: number;
  perspective?: ChoroplethPerspective;
  zoomTransition?: ChoroplethZoomTransition;
  /** Clears drag/wheel zoom before a camera move so the two don't compound. */
  onBeforeFocus?: () => void;
}

export interface ChoroplethCameraController {
  api: ChoroplethCameraApi;
  cameraRef: RefObject<SVGGElement | null>;
  svgRef: RefObject<SVGSVGElement | null>;
  planeRef: RefObject<HTMLDivElement | null>;
  yaw: MotionValue<number>;
  tilt: MotionValue<number>;
  depth: number;
  hasPerspective: boolean;
  /** Viewport edge fade in % per side; 0 when there's no perspective. */
  edgeFade: number;
  /** Fade is showing: the map is tilted or the camera is focused. */
  edgeFadeActive: boolean;
  onPointerDown: (event: React.PointerEvent) => void;
  onPointerMove: (event: React.PointerEvent) => void;
  onPointerLeave: () => void;
}

export function useChoroplethCameraController({
  width,
  height,
  mercator,
  features,
  clickToZoom,
  focusMaxZoom,
  perspective,
  zoomTransition,
  onBeforeFocus,
}: UseCameraOptions): ChoroplethCameraController {
  const reduceMotion = useReducedMotion();
  const cameraRef = useRef<SVGGElement | null>(null);
  const svgRef = useRef<SVGSVGElement | null>(null);
  const planeRef = useRef<HTMLDivElement | null>(null);
  const viewRef = useRef<View>({ cx: width / 2, cy: height / 2, k: 1 });
  const flight = useRef<AnimationPlaybackControls | null>(null);
  const yawAnim = useRef<AnimationPlaybackControls | null>(null);
  const tiltAnim = useRef<AnimationPlaybackControls | null>(null);
  const pressRef = useRef<{ x: number; y: number; moved: boolean } | null>(
    null
  );
  const [focusedKey, setFocusedKey] = useState<string | null>(null);

  const overview = perspective?.overview;
  const focus = perspective?.focus;
  const overviewView = overview?.view ?? "flat";
  const overviewYaw = overview?.yaw ?? DEFAULT_YAW;
  const overviewTilt = overview?.tilt ?? 0;
  const focusView = focus?.view;
  const focusYaw = focus?.yaw ?? overviewYaw;
  const focusTilt = focus?.tilt ?? overviewTilt;
  const depth = perspective?.depth ?? 1600;

  const overviewStaticYaw =
    overviewView === "pointer" ? 0 : signedYaw(overviewView, overviewYaw);

  const yaw = useMotionValue(overviewStaticYaw);
  const tilt = useMotionValue(overviewTilt);

  const hasPerspective =
    perspective !== undefined &&
    (overviewView !== "flat" ||
      overviewTilt !== 0 ||
      (focusView !== undefined && focusView !== "flat") ||
      focusTilt !== 0);

  const duration = reduceMotion ? 0 : (zoomTransition?.duration ?? 700) / 1000;
  const easeKey = (zoomTransition?.ease ?? DEFAULT_CHOROPLETH_ZOOM_EASE).join(
    ","
  );
  const ease = useMemo(
    () => easeKey.split(",").map(Number) as [number, number, number, number],
    [easeKey]
  );

  const applyView = useCallback(
    (view: View) => {
      viewRef.current = view;
      const tx = width / 2 - view.k * view.cx;
      const ty = height / 2 - view.k * view.cy;
      cameraRef.current?.setAttribute(
        "transform",
        view.k === 1 && tx === 0 && ty === 0
          ? ""
          : `translate(${tx} ${ty}) scale(${view.k})`
      );
      svgRef.current?.style.setProperty(
        CHOROPLETH_CAMERA_SCALE_VAR,
        String(view.k)
      );
    },
    [width, height]
  );

  const moveAngles = useCallback(
    (nextYaw: number, nextTilt: number) => {
      yawAnim.current?.stop();
      tiltAnim.current?.stop();
      if (duration === 0) {
        yaw.set(nextYaw);
        tilt.set(nextTilt);
        return;
      }
      const options = { duration, ease };
      yawAnim.current = animate(yaw, nextYaw, options);
      tiltAnim.current = animate(tilt, nextTilt, options);
    },
    [duration, ease, tilt, yaw]
  );

  const flyTo = useCallback(
    (target: View) => {
      flight.current?.stop();
      if (duration === 0) {
        applyView(target);
        return;
      }
      const from = { ...viewRef.current };
      const logFrom = Math.log(from.k);
      const logTo = Math.log(target.k);
      // Centre moves linearly, scale geometrically: one steady camera move
      // instead of a swoop that overshoots on the way in.
      flight.current = animate(0, 1, {
        duration,
        ease,
        onUpdate: (t) =>
          applyView({
            cx: from.cx + (target.cx - from.cx) * t,
            cy: from.cy + (target.cy - from.cy) * t,
            k: Math.exp(logFrom + (logTo - logFrom) * t),
          }),
      });
    },
    [applyView, duration, ease]
  );

  const focusAngles = useCallback(
    (cx: number) => {
      if (!perspective) {
        return;
      }
      let side: ChoroplethViewSide;
      if (focusView === "auto") {
        side = cx < width / 2 ? "west" : "east";
      } else if (focusView) {
        side = focusView;
      } else {
        side = overviewView === "pointer" ? "flat" : overviewView;
      }
      moveAngles(signedYaw(side, focusYaw), focusTilt);
    },
    [
      focusTilt,
      focusView,
      focusYaw,
      moveAngles,
      overviewView,
      perspective,
      width,
    ]
  );

  const reset = useCallback(() => {
    setFocusedKey(null);
    flyTo({ cx: width / 2, cy: height / 2, k: 1 });
    moveAngles(overviewStaticYaw, overviewTilt);
  }, [flyTo, height, moveAngles, overviewStaticYaw, overviewTilt, width]);

  const focusFeature = useCallback(
    (index: number) => {
      const key = `feature:${index}`;
      if (focusedKey === key) {
        reset();
        return;
      }
      const feature = features[index];
      if (!feature) {
        return;
      }
      const [[x0, y0], [x1, y1]] = mercator.path.bounds(mainland(feature));
      if (![x0, y0, x1, y1].every(Number.isFinite)) {
        return;
      }
      const k = Math.min(
        focusMaxZoom,
        Math.max(
          1,
          0.7 * Math.min(width / (x1 - x0 || 1), height / (y1 - y0 || 1))
        )
      );
      const cx = (x0 + x1) / 2;
      onBeforeFocus?.();
      setFocusedKey(key);
      flyTo({ cx, cy: (y0 + y1) / 2, k });
      focusAngles(cx);
    },
    [
      features,
      flyTo,
      focusAngles,
      focusMaxZoom,
      focusedKey,
      height,
      mercator,
      onBeforeFocus,
      reset,
      width,
    ]
  );

  const focusPoint = useCallback(
    (coordinates: [number, number], key: string) => {
      const pointKey = `point:${key}`;
      if (focusedKey === pointKey) {
        reset();
        return;
      }
      const projected = mercator.projection(coordinates);
      if (!projected) {
        return;
      }
      const [cx, cy] = projected;
      onBeforeFocus?.();
      setFocusedKey(pointKey);
      flyTo({ cx, cy, k: Math.min(focusMaxZoom, 4) });
      focusAngles(cx);
    },
    [
      focusAngles,
      flyTo,
      focusMaxZoom,
      focusedKey,
      mercator,
      onBeforeFocus,
      reset,
    ]
  );

  // Size change: projection is rebuilt, so the camera starts over.
  useEffect(() => {
    flight.current?.stop();
    applyView({ cx: width / 2, cy: height / 2, k: 1 });
    setFocusedKey(null);
  }, [applyView, width, height]);

  // Perspective settings changed: settle on the matching angles.
  useEffect(() => {
    if (focusedKey === null) {
      moveAngles(overviewStaticYaw, overviewTilt);
    }
  }, [focusedKey, moveAngles, overviewStaticYaw, overviewTilt]);

  // Plane transform follows the motion values without React renders.
  useEffect(() => {
    const write = () => {
      const plane = planeRef.current;
      if (plane) {
        plane.style.transform = `rotateX(${tilt.get()}deg) rotateY(${yaw.get()}deg)`;
      }
    };
    write();
    const offYaw = yaw.on("change", write);
    const offTilt = tilt.on("change", write);
    return () => {
      offYaw();
      offTilt();
    };
  }, [tilt, yaw]);

  useEffect(() => {
    if (!clickToZoom) {
      return;
    }
    const onKey = (event: KeyboardEvent) => {
      if (event.key === "Escape" && focusedKey !== null) {
        reset();
      }
    };
    window.addEventListener("keydown", onKey);
    return () => window.removeEventListener("keydown", onKey);
  }, [clickToZoom, focusedKey, reset]);

  useEffect(
    () => () => {
      flight.current?.stop();
      yawAnim.current?.stop();
      tiltAnim.current?.stop();
    },
    []
  );

  const followsPointer =
    perspective !== undefined &&
    overviewView === "pointer" &&
    focusedKey === null &&
    !reduceMotion;

  const onPointerMove = useCallback(
    (event: React.PointerEvent) => {
      const press = pressRef.current;
      if (
        press &&
        Math.hypot(event.clientX - press.x, event.clientY - press.y) >
          DRAG_CLICK_TOLERANCE
      ) {
        press.moved = true;
      }
      if (!followsPointer) {
        return;
      }
      const box = event.currentTarget.getBoundingClientRect();
      const t = Math.min(
        1,
        Math.max(0, (event.clientX - box.left) / box.width)
      );
      // Left edge → seen from the west, right edge → from the east.
      yawAnim.current?.stop();
      yawAnim.current = animate(
        yaw,
        overviewYaw - 2 * overviewYaw * t,
        POINTER_SPRING
      );
    },
    [followsPointer, overviewYaw, yaw]
  );

  const onPointerLeave = useCallback(() => {
    if (!followsPointer) {
      return;
    }
    yawAnim.current?.stop();
    yawAnim.current = animate(yaw, 0, POINTER_SPRING);
  }, [followsPointer, yaw]);

  const onPointerDown = useCallback((event: React.PointerEvent) => {
    pressRef.current = { x: event.clientX, y: event.clientY, moved: false };
  }, []);

  const wasDrag = useCallback(() => pressRef.current?.moved ?? false, []);

  const api = useMemo<ChoroplethCameraApi>(
    () => ({
      enabled: clickToZoom,
      focusedKey,
      focusedFeatureIndex: focusedKey?.startsWith("feature:")
        ? Number(focusedKey.slice("feature:".length))
        : null,
      maxZoom: focusMaxZoom,
      isHoverable: (key: string) => focusedKey === null || focusedKey === key,
      focusFeature,
      focusPoint,
      reset,
      wasDrag,
    }),
    [
      clickToZoom,
      focusFeature,
      focusMaxZoom,
      focusPoint,
      focusedKey,
      reset,
      wasDrag,
    ]
  );

  return {
    api,
    cameraRef,
    svgRef,
    planeRef,
    yaw,
    tilt,
    depth,
    hasPerspective,
    edgeFade: hasPerspective
      ? Math.min(45, Math.max(0, perspective?.edgeFade ?? 0))
      : 0,
    edgeFadeActive:
      focusedKey !== null || overviewView !== "flat" || overviewTilt !== 0,
    onPointerDown,
    onPointerMove,
    onPointerLeave,
  };
}

