"use client";

import { m } from "motion/react";
import { memo, useCallback, useId, useMemo } from "react";
import { useMountProgress } from "../use-mount-progress";
import {
  CHOROPLETH_CAMERA_SCALE_VAR,
  useChoroplethCamera,
} from "./choropleth-camera";
import {
  type ChoroplethFeature,
  defaultChoroplethColors,
  useChoroplethInteraction,
  useChoroplethStable,
} from "./choropleth-context";

export type ChoroplethDotLattice = "hex" | "square";

export interface ChoroplethDotGridProps {
  /** Distance between dot centres in px. Default: 7 */
  gap?: number;
  /** Dot diameter as a fraction of `gap` (0–1). Default: 0.7 */
  dotSize?: number;
  /**
   * Dot diameter (fraction of `gap`) at the camera's max zoom — dots grow
   * smoothly toward it as you zoom in, on top of the zoom itself. Default: 0.9
   */
  zoomDotSize?: number;
  /** Fade the ocean dots out while the camera is focused on a region. Default: true */
  hideOceanOnFocus?: boolean;
  /** `hex` offsets every other row; `square` is a plain grid. Default: "hex" */
  lattice?: ChoroplethDotLattice;
  /** Draw the grid over oceans too, so the whole map is one dot field. Default: true */
  showOcean?: boolean;
  /** Ocean dot colour. Default: `var(--chart-scale-01)` */
  oceanColor?: string;
  /** Ocean dot opacity. Default: 0.55 */
  oceanOpacity?: number;
  /** Ocean dot size relative to land dots. Default: 0.55 */
  oceanDotScale?: number;
  /**
   * Fade the grid out toward the map's edges, as % of width/height per side.
   * `0` keeps hard edges. Default: 12
   */
  edgeFade?: number;
  /** Uniform dot colour (overrides `getFeatureColor`). */
  fill?: string;
  /** Per-region dot colour. */
  getFeatureColor?: (feature: ChoroplethFeature, index: number) => string;
  /** Opacity of other regions while one is hovered. Default: 0.4 */
  fadedOpacity?: number;
}

interface Dot {
  x: number;
  y: number;
  /** Feature index, or -1 for ocean. */
  feature: number;
}

/**
 * One lattice over the whole map. Each dot belongs to the region its centre
 * lands on (read from an index-coloured canvas) and is always drawn whole —
 * coastlines and borders never clip a dot.
 */
export function buildChoroplethLattice(
  featurePaths: readonly (string | null)[],
  width: number,
  height: number,
  gap: number,
  lattice: ChoroplethDotLattice
): Dot[] {
  if (typeof document === "undefined" || width < 1 || height < 1 || gap < 1) {
    return [];
  }
  const canvas = document.createElement("canvas");
  canvas.width = Math.ceil(width);
  canvas.height = Math.ceil(height);
  const ctx = canvas.getContext("2d", { willReadFrequently: true });
  if (!ctx) {
    return [];
  }
  featurePaths.forEach((d, index) => {
    if (!d) {
      return;
    }
    const id = index + 1;
    ctx.fillStyle = `rgb(${id % 256},${Math.floor(id / 256) % 256},${Math.floor(id / 65_536)})`;
    ctx.fill(new Path2D(d));
  });
  const pixels = ctx.getImageData(0, 0, canvas.width, canvas.height).data;
  const rowStep = lattice === "hex" ? gap * 0.866 : gap;
  const dots: Dot[] = [];
  let row = 0;
  for (let y = gap / 2; y < height; y += rowStep, row++) {
    const offset = lattice === "hex" && row % 2 === 1 ? gap / 2 : 0;
    for (let x = gap / 2 + offset; x < width; x += gap) {
      const id = regionIdAt(pixels, canvas.width, x, y);
      dots.push({
        x,
        y,
        feature: id > 0 && id <= featurePaths.length ? id - 1 : -1,
      });
    }
  }
  return dots;
}

/** Region id encoded in the hit canvas at (x, y); 0 = ocean. */
function regionIdAt(
  pixels: Uint8ClampedArray,
  canvasWidth: number,
  x: number,
  y: number
) {
  const p = (Math.floor(y) * canvasWidth + Math.floor(x)) * 4;
  // Unpremultiplied: an anti-aliased edge pixel still carries its id.
  if ((pixels[p + 3] ?? 0) === 0) {
    return 0;
  }
  return (
    (pixels[p] ?? 0) +
    (pixels[p + 1] ?? 0) * 256 +
    (pixels[p + 2] ?? 0) * 65_536
  );
}

/**
 * A dot is a zero-length segment drawn with a round cap, so its size is the
 * path's `stroke-width` — one CSS value that can follow the zoom live.
 */
function dot(x: number, y: number) {
  return `M${x} ${y}h0`;
}

function fadeStops(lengthPercent: number) {
  const edge = Math.min(45, Math.max(0, lengthPercent));
  return [
    { offset: "0%", opacity: 0 },
    { offset: `${edge}%`, opacity: 1 },
    { offset: `${100 - edge}%`, opacity: 1 },
    { offset: "100%", opacity: 0 },
  ];
}

export const ChoroplethDotGrid = memo(function ChoroplethDotGrid({
  gap = 7,
  dotSize = 0.7,
  zoomDotSize = 0.9,
  hideOceanOnFocus = true,
  lattice = "hex",
  showOcean = true,
  oceanColor = "var(--chart-scale-01)",
  oceanOpacity = 0.55,
  oceanDotScale = 0.55,
  edgeFade = 12,
  fill,
  getFeatureColor,
  fadedOpacity = 0.4,
}: ChoroplethDotGridProps) {
  const {
    features,
    featurePaths,
    width,
    height,
    enterTransition,
    revealEpoch,
  } = useChoroplethStable();
  const { hoveredFeatureIndex, setHoveredFeatureIndex, setTooltipData } =
    useChoroplethInteraction();
  const camera = useChoroplethCamera();
  const uid = useId().replace(/:/g, "");

  const dots = useMemo(
    () => buildChoroplethLattice(featurePaths, width, height, gap, lattice),
    [featurePaths, width, height, gap, lattice]
  );

  const layers = useMemo(() => {
    const byFeature = new Map<number, string[]>();
    const ocean: string[] = [];
    for (const { x, y, feature } of dots) {
      if (feature < 0) {
        ocean.push(dot(x, y));
        continue;
      }
      const list = byFeature.get(feature);
      if (list) {
        list.push(dot(x, y));
      } else {
        byFeature.set(feature, [dot(x, y)]);
      }
    }
    const regions = [...byFeature.entries()].map(([index, parts]) => {
      const feature = features[index];
      let color = fill;
      if (!color && feature && getFeatureColor) {
        color = getFeatureColor(feature, index);
      }
      color ??=
        defaultChoroplethColors[index % defaultChoroplethColors.length] ??
        "var(--chart-1)";
      return { index, d: parts.join(""), fill: color };
    });
    return { ocean: ocean.join(""), regions };
  }, [dots, features, fill, getFeatureColor]);

  const clampSize = (size: number) => Math.min(1, Math.max(0.05, size));
  const baseSize = clampSize(dotSize);
  const growth = clampSize(zoomDotSize) - baseSize;
  // 0 at the overview, 1 at the camera's max zoom; follows every frame.
  const zoomProgress = `min(1, max(0, (var(${CHOROPLETH_CAMERA_SCALE_VAR}, 1) - 1) / ${Math.max(0.01, camera.maxZoom - 1)}))`;
  const landStrokeWidth =
    growth === 0
      ? `${gap * baseSize}px`
      : `calc(${gap}px * (${baseSize} + ${growth} * ${zoomProgress}))`;
  const oceanStrokeWidth = `${gap * baseSize * oceanDotScale}px`;
  const oceanHidden = hideOceanOnFocus && camera.focusedKey !== null;

  const enterProgress = useMountProgress(
    enterTransition,
    0,
    `choropleth-dots-${revealEpoch}`
  );

  const handleEnter = useCallback(
    (index: number, event: React.MouseEvent<SVGPathElement>) => {
      const feature = features[index];
      if (!(feature && camera.isHoverable(`feature:${index}`))) {
        return;
      }
      const target = event.currentTarget as SVGGraphicsElement;
      const box = (target.ownerSVGElement ?? target).getBoundingClientRect();
      setHoveredFeatureIndex(index);
      setTooltipData({
        featureIndex: index,
        x: event.clientX - box.left,
        y: event.clientY - box.top,
        feature,
      });
    },
    [camera, features, setHoveredFeatureIndex, setTooltipData]
  );

  const handleLeave = useCallback(() => {
    setHoveredFeatureIndex(null);
    setTooltipData(null);
  }, [setHoveredFeatureIndex, setTooltipData]);

  const focusedIndex = camera.focusedFeatureIndex;
  // Focused region first so a hovered neighbour draws on top of it.
  const lit = layers.regions
    .filter(
      (region) =>
        region.index === hoveredFeatureIndex || region.index === focusedIndex
    )
    .sort((a) => (a.index === hoveredFeatureIndex ? 1 : -1));
  const dimmed = hoveredFeatureIndex !== null;

  const maskId = `choropleth-dots-fade-${uid}`;
  const hGradient = `${maskId}-h`;
  const vGradient = `${maskId}-v`;
  const hMask = `${maskId}-hm`;
  const stops = fadeStops(edgeFade);

  return (
    <g className="choropleth-dot-grid">
      {edgeFade > 0 ? (
        <defs>
          <linearGradient id={hGradient} x1="0" x2="1" y1="0" y2="0">
            {stops.map((stop) => (
              <stop
                key={stop.offset}
                offset={stop.offset}
                stopColor="white"
                stopOpacity={stop.opacity}
              />
            ))}
          </linearGradient>
          <linearGradient id={vGradient} x1="0" x2="0" y1="0" y2="1">
            {stops.map((stop) => (
              <stop
                key={stop.offset}
                offset={stop.offset}
                stopColor="white"
                stopOpacity={stop.opacity}
              />
            ))}
          </linearGradient>
          <mask
            height={height}
            id={hMask}
            maskUnits="userSpaceOnUse"
            width={width}
            x={0}
            y={0}
          >
            <rect fill={`url(#${hGradient})`} height={height} width={width} />
          </mask>
          <mask
            height={height}
            id={maskId}
            maskUnits="userSpaceOnUse"
            width={width}
            x={0}
            y={0}
          >
            <g mask={`url(#${hMask})`}>
              <rect fill={`url(#${vGradient})`} height={height} width={width} />
            </g>
          </mask>
        </defs>
      ) : null}
      <m.g
        mask={edgeFade > 0 ? `url(#${maskId})` : undefined}
        pointerEvents="none"
        style={{ opacity: enterProgress }}
      >
        {showOcean && layers.ocean ? (
          <path
            d={layers.ocean}
            fill="none"
            stroke={oceanColor}
            strokeLinecap="round"
            style={{
              opacity: oceanHidden ? 0 : oceanOpacity,
              strokeWidth: oceanStrokeWidth,
              transition: "opacity 0.3s ease-out",
            }}
          />
        ) : null}
        <g
          fill="none"
          strokeLinecap="round"
          style={{ strokeWidth: landStrokeWidth }}
        >
          <g
            opacity={dimmed ? fadedOpacity : 1}
            style={{ transition: "opacity 0.18s ease-out" }}
          >
            {layers.regions.map((region) => (
              <path d={region.d} key={region.index} stroke={region.fill} />
            ))}
          </g>
          {dimmed
            ? lit.map((region) => (
                <path
                  d={region.d}
                  key={`lit-${region.index}`}
                  stroke={region.fill}
                />
              ))
            : null}
        </g>
      </m.g>
      {/* Invisible region shapes: hover + click targets for the dots above. */}
      <g fill="transparent">
        {featurePaths.map((d, index) =>
          d ? (
            // biome-ignore lint/a11y/noStaticElementInteractions: SVG path used as hover hitbox
            <path
              className="cursor-pointer"
              d={d}
              key={index}
              onClick={() => {
                if (camera.enabled && !camera.wasDrag()) {
                  camera.focusFeature(index);
                }
              }}
              onMouseEnter={(event) => handleEnter(index, event)}
              onMouseLeave={handleLeave}
            />
          ) : null
        )}
      </g>
    </g>
  );
});

ChoroplethDotGrid.displayName = "ChoroplethDotGrid";

export default ChoroplethDotGrid;

"use client";

import { memo, useCallback, useId } from "react";
import { cn } from "@/lib/utils";
import {
  CHOROPLETH_CAMERA_SCALE_VAR,
  useChoroplethCamera,
} from "./choropleth-camera";
import {
  useChoroplethInteraction,
  useChoroplethStable,
  useChoroplethZoom,
} from "./choropleth-context";

export type ChoroplethMarkerShape =
  | "circle"
  | "triangle"
  | "square"
  | "diamond"
  | "pin";

export type ChoroplethMarkerPulse = "none" | "hover" | "always";

export interface ChoroplethMarkerProps {
  /** `[longitude, latitude]` */
  coordinates: [number, number];
  /** Name shown in the tooltip (and next to the marker with `showLabel`). */
  label: string;
  /** Default: "circle" */
  shape?: ChoroplethMarkerShape;
  /** Marker size in px. It stays this size while the map zooms. Default: 9 */
  size?: number;
  /** Default: `var(--foreground)` */
  color?: string;
  /** Outline colour; omit for no outline. */
  stroke?: string;
  /** Outline width in px (only with `stroke`). Default: 1.5 */
  strokeWidth?: number;
  /** Ripple ring: off, while hovered/focused, or always. Default: "hover" */
  pulse?: ChoroplethMarkerPulse;
  /** Soft outer glow blur in px; `0` turns it off. Default: 0 */
  glow?: number;
  /** Always show the label beside the marker. Default: false */
  showLabel?: boolean;
  className?: string;
}

function shapePath(shape: ChoroplethMarkerShape, r: number) {
  switch (shape) {
    case "triangle":
      return `M0,${-r * 1.15}L${r * 1.05},${r * 0.7}L${-r * 1.05},${r * 0.7}Z`;
    case "square": {
      const s = r * 0.88;
      return `M${-s},${-s}H${s}V${s}H${-s}Z`;
    }
    case "diamond":
      return `M0,${-r * 1.2}L${r * 1.2},0L0,${r * 1.2}L${-r * 1.2},0Z`;
    case "pin": {
      // Tip sits on the coordinate; round head above it.
      const cy = -r * 1.9;
      const hx = r * 0.82;
      const hy = cy + r * 0.57;
      return `M0,0L${-hx},${hy}A${r},${r} 0 1,1 ${hx},${hy}Z`;
    }
    default:
      return `M${-r},0a${r},${r} 0 1,0 ${2 * r},0a${r},${r} 0 1,0 ${-2 * r},0`;
  }
}

const PULSE_CLASS: Record<ChoroplethMarkerPulse, string> = {
  always: "animate-ping",
  hover:
    "group-hover/marker:animate-ping group-focus-visible/marker:animate-ping",
  none: "hidden",
};

/** Stable per-label offset so "always" pulses don't fire in lockstep. */
function pulseDelay(label: string) {
  let h = 0;
  for (let i = 0; i < label.length; i++) {
    h = (h * 31 + label.charCodeAt(i)) % 997;
  }
  return `${-(h % 10) * 110}ms`;
}

export const ChoroplethMarker = memo(function ChoroplethMarker({
  coordinates,
  label,
  shape = "circle",
  size = 9,
  color = "var(--foreground)",
  stroke,
  strokeWidth = 1.5,
  pulse = "hover",
  glow = 0,
  showLabel = false,
  className,
}: ChoroplethMarkerProps) {
  const { projectPoint } = useChoroplethStable();
  const { setMarkerTooltip, setHoveredFeatureIndex, setTooltipData } =
    useChoroplethInteraction();
  const { zoom } = useChoroplethZoom();
  const camera = useChoroplethCamera();
  const glowId = `choropleth-marker-glow-${useId().replace(/:/g, "")}`;

  const [lon, lat] = coordinates;
  const point = projectPoint([lon, lat]);

  const hoverable = camera.isHoverable(`point:${label}`);
  const show = useCallback(() => {
    if (!hoverable) {
      return;
    }
    setHoveredFeatureIndex(null);
    setTooltipData(null);
    setMarkerTooltip?.({ label, coordinates: [lon, lat] });
  }, [
    hoverable,
    label,
    lat,
    lon,
    setHoveredFeatureIndex,
    setMarkerTooltip,
    setTooltipData,
  ]);

  const hide = useCallback(() => setMarkerTooltip?.(null), [setMarkerTooltip]);

  const focus = useCallback(() => {
    if (camera.enabled) {
      camera.focusPoint([lon, lat], label);
    }
  }, [camera, label, lat, lon]);

  if (!point) {
    return null;
  }

  const r = size / 2;
  const d = shapePath(shape, r);
  const isPin = shape === "pin";
  const headY = isPin ? -r * 1.9 : 0;
  const zoomScale = zoom?.transformMatrix.scaleX ?? 1;
  const interactive = camera.enabled;
  const pulseClass =
    pulse === "hover" && !hoverable ? "hidden" : PULSE_CLASS[pulse];
  // Zoomed in on something else: stay clickable, skip hover feedback.
  const hoverScale = hoverable ? "group-hover/marker:scale-115" : "";

  return (
    <g transform={`translate(${point[0]} ${point[1]})`}>
      {/* biome-ignore lint/a11y/noStaticElementInteractions: role set when clickable */}
      <g
        aria-label={interactive ? `Zoom to ${label}` : undefined}
        className={cn(
          "group/marker outline-none",
          interactive && "cursor-pointer",
          className
        )}
        onBlur={hide}
        onClick={(event) => {
          event.stopPropagation();
          if (!camera.wasDrag()) {
            focus();
          }
        }}
        onFocus={show}
        onKeyDown={(event) => {
          if (event.key === "Enter" || event.key === " ") {
            event.preventDefault();
            focus();
          }
        }}
        onMouseEnter={show}
        onMouseLeave={hide}
        role={interactive ? "button" : undefined}
        style={{
          // Constant on-screen size while the camera and drag-zoom scale the map.
          transform: `scale(calc(1 / (var(${CHOROPLETH_CAMERA_SCALE_VAR}, 1) * ${zoomScale})))`,
        }}
        tabIndex={interactive ? 0 : undefined}
      >
        {/* Hit area stays still while the shape scales. */}
        <circle cy={headY * 0.6} fill="transparent" r={Math.max(r * 2, 22)} />
        <circle
          className={cn(
            "pointer-events-none origin-center [transform-box:fill-box] motion-reduce:animate-none",
            pulseClass
          )}
          cy={headY}
          fill="none"
          r={r}
          stroke={color}
          strokeWidth={1.5}
          style={
            pulse === "always"
              ? { animationDelay: pulseDelay(label) }
              : undefined
          }
        />
        {glow > 0 ? (
          <>
            <defs>
              <filter
                height="500%"
                id={glowId}
                width="500%"
                x="-200%"
                y="-200%"
              >
                <feGaussianBlur stdDeviation={glow} />
              </filter>
            </defs>
            <path
              className={cn(
                hoverable &&
                  "group-hover/marker:scale-115 group-hover/marker:opacity-100",
                "pointer-events-none opacity-55 transition-[opacity,scale] duration-150 ease-out [transform-box:fill-box] group-focus-visible/marker:opacity-100 group-focus-visible/marker:opacity-100 motion-reduce:transition-none",
                isPin ? "origin-bottom" : "origin-center"
              )}
              d={d}
              fill={color}
              filter={`url(#${glowId})`}
            />
          </>
        ) : null}
        <path
          className={cn(
            hoverScale,
            "transition-[scale] duration-150 ease-out [transform-box:fill-box] group-focus-visible/marker:stroke-foreground motion-reduce:transition-none",
            isPin ? "origin-bottom" : "origin-center"
          )}
          d={d}
          fill={color}
          paintOrder="stroke"
          // No outline unless asked for; keyboard focus still draws one.
          stroke={stroke ?? "none"}
          strokeWidth={stroke ? strokeWidth : 2}
        />
        {isPin ? (
          <circle
            className="pointer-events-none"
            cy={headY}
            fill="var(--background)"
            r={r * 0.38}
          />
        ) : null}
        {showLabel ? (
          <text
            className="pointer-events-none select-none font-medium text-[11px]"
            dy="0.35em"
            fill="var(--foreground)"
            paintOrder="stroke"
            stroke="var(--background)"
            strokeLinejoin="round"
            strokeWidth={3}
            x={r + 6}
            y={headY}
          >
            {label}
          </text>
        ) : null}
      </g>
    </g>
  );
});

